	[RegNo] [varchar](20) NOT NULL,
	CERTIFICATENO [varchar](20) NULL,
	[Status] [varchar](1) NULL,
	[Last_Opr] [varchar](10) NULL,
	[Last_Update] [smalldatetime] NULL,
	[PDate] [smalldatetime] NOT NULL,
	[ErrMsg] [varchar](255) NULL
	)
END
