Create Function [dbo].[ICPS_PolicyDeductible](@P_ANO as int, @P_Category as varchar(1)) 
RETURNS VarChar(512)    
With SchemaBinding
AS    
BEGIN    
 Declare @Remarks as varchar(512)    
 Declare @Remark as varchar(512)   
 Declare @Rate  as varchar(512)  
 Declare @Unit as varchar(512)  
      
 Select @Remarks=''    
 DECLARE AccDed_Cursor CURSOR FOR    

 Select Distinct Cast(AccDed.Remarks as varchar(512)) as Remark from dbo.AccDed, dbo.Acceptance, dbo.Cover, dbo.RClass 
 Where Cover.CNO=Acceptance.CNO and AccDed.ANO=Acceptance.ANO and RClass.TOC=Cover.TOC and RClass.TOR=AccDed.TOR and (RClass.Category=@P_Category or @P_Category='') 
   
 OPEN AccDed_Cursor    
 FETCH FROM AccDed_Cursor into @Remark
 WHILE @@FETCH_STATUS = 0    
 BEGIN    
    if @Remarks=''    
    BEGIN    
  Select @Remarks=@Remark
    End    
     Else    
    BEGIN    
     Select @Remarks=substring(@Remarks+'|'+@Remark,1,512)    
    End    
    FETCH NEXT FROM AccDed_Cursor into @Remark
 End    
 Close AccDed_Cursor    
 Deallocate AccDed_Cursor    
 Return (@Remarks)    
End    



GO
