	[DueDate] [smalldatetime] NULL,
	[Lapse] [int] NULL,
	[Premium] [float] NULL,
	[Discount] [float] NULL,
	[Commission] [float] NULL,
	[Fee] [float] NULL,
	[Duty] [float] NULL,
	[Payment] [float] NULL,
	[Insured] [varchar](512) NULL,
	[Remarks] [varchar](255) NULL,
	[Status] [varchar](1) NULL,
	[Last_Opr] [varchar](10) NULL,
	[Last_Update] [smalldatetime] NULL,
	[CUserID] [varchar](10) NULL,
	[CloseDate] [smalldatetime] NULL,
	[PUserID] [varchar](10) NULL,
	[PUserDate] [smalldatetime] NULL,
	[ErrMsg] [varchar](255) NULL,
	[PStatus] [varchar](1) NULL,
 CONSTRAINT [I_ALBucket] PRIMARY KEY CLUSTERED 
(
	[PID] ASC
)WITH (PAD_INDEX  = OFF, STATISTICS_NORECOMPUTE  = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS  = ON, ALLOW_PAGE_LOCKS  = ON) ON [PRIMARY],
 CONSTRAINT [I_ALBucket_A_PolicyNo] UNIQUE NONCLUSTERED 
