Drop Procedure AutoInforce_Process
GO
CREATE Procedure AutoInforce_Process(@P_PDate as smalldatetime)                                          
as                                 
Select AIBucket.ADate, AIBucket.PID, Acceptance.ANO, Acceptance.LANO, Acceptance.RegNo            
from AIBucket, Acceptance, Cover              
where AIBucket.Status='R' and Acceptance.RegNo=AIBucket.RegNo and Acceptance.CertificateNo=AIBucket.CertificateNo and Cover.CNO=Acceptance.CNO           
and (Acceptance.LANO=-1 or Acceptance.ANO=Acceptance.LANO or Cover.OpenFlag=1)            
and Cover.CStatus='A' and Acceptance.AStatus='W'   
and Acceptance.CDate<=AIBucket.Last_Update  
GO


