IF NOT EXISTS(SELECT * FROM sys.columns WHERE Name = N'RenewalTo' AND Object_ID = Object_ID(N'Renewal'))
BEGIN
ALTER TABLE dbo.Renewal ADD
	RenewalTo int NULL
END
GO
IF NOT EXISTS (SELECT * FROM SYS.EXTENDED_PROPERTIES WHERE [major_id] = OBJECT_ID('Renewal') AND [name] = N'MS_Description' AND [minor_id] = (SELECT [column_id] FROM SYS.COLUMNS WHERE [name] = 'RenewalTo' AND [object_id] = OBJECT_ID('Renewal')))
BEGIN
DECLARE @v sql_variant 
SET @v = N'Renewal To (0 : Default, 1 : Individual)'
EXECUTE sp_addextendedproperty N'MS_Description', @v, N'SCHEMA', N'dbo', N'TABLE', N'Renewal', N'COLUMN', N'RenewalTo'
END
GO
ALTER TABLE dbo.Renewal SET (LOCK_ESCALATION = TABLE)
GO

