-- 9 December 2014 : Penambahan Field Inter Office Flag di Table Account - untuk membatasi Account yang bisa untuk Inter Office
/* To prevent any potential data loss issues, you should review this script in detail before running it outside the context of the database designer.*/

SET QUOTED_IDENTIFIER ON
SET ARITHABORT ON
SET NUMERIC_ROUNDABORT OFF
SET CONCAT_NULL_YIELDS_NULL ON
SET ANSI_NULLS ON
SET ANSI_PADDING ON
SET ANSI_WARNINGS ON


GO
IF NOT EXISTS(SELECT * FROM sys.columns WHERE Name = N'Inter_Flag' AND Object_ID = Object_ID(N'Account'))
BEGIN
ALTER TABLE dbo.Account ADD
	Inter_Flag bit NULL
END
GO
IF NOT EXISTS (SELECT * FROM SYS.EXTENDED_PROPERTIES WHERE [major_id] = OBJECT_ID('Account') AND [name] = N'MS_Description' AND [minor_id] = (SELECT [column_id] FROM SYS.COLUMNS WHERE [name] = 'Inter_Flag' AND [object_id] = OBJECT_ID('Account')))
BEGIN
DECLARE @v sql_variant 
SET @v = N'Inter-Office Flag (0 : No, 1 : Yes For Branch Inter-Office Account)'
EXECUTE sp_addextendedproperty N'MS_Description', @v, N'SCHEMA', N'dbo', N'TABLE', N'Account', N'COLUMN', N'Inter_Flag'
END
GO
IF NOT EXISTS(SELECT * FROM sys.default_constraints WHERE object_id = OBJECT_ID('[dbo].[DF_Account_Inter_Flag]') AND parent_object_id = OBJECT_ID('[dbo].[Account]'))
BEGIN
ALTER TABLE dbo.Account ADD CONSTRAINT
	DF_Account_Inter_Flag DEFAULT (0) FOR Inter_Flag
END
GO
ALTER TABLE dbo.Account SET (LOCK_ESCALATION = TABLE)
GO

GO

GO

