--31 March 2015 : Penambahan Table VoucherPic untuk penyimapan Document untuk Payment / Receipt Voucher
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].VoucherPic') AND type in (N'U'))
BEGIN
	CREATE TABLE [dbo].[VoucherPic]
	(
		[Voucher] [varchar](20) NOT NULL,
		[ImageID] [int] NOT NULL,
		[FileType] [varchar](10) NULL,
		[Title] [varchar](255) NULL,
		[Remark] [text] NULL,
		[Last_Opr] [varchar](10) NULL,
		[Last_Update] [smalldatetime] NULL,
		CONSTRAINT [I_VoucherPic] PRIMARY KEY NONCLUSTERED 
		(
			[Voucher] ASC,
			[ImageID] ASC
		)WITH (PAD_INDEX  = OFF, STATISTICS_NORECOMPUTE  = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS  = ON, ALLOW_PAGE_LOCKS  = ON) ON [PRIMARY]
	) ON [PRIMARY] TEXTIMAGE_ON [PRIMARY]
	EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Voucher No. (Auto Generated)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'VoucherPic', @level2type=N'COLUMN',@level2name=N'Voucher'
	EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Image ID (see SysImage)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'VoucherPic', @level2type=N'COLUMN',@level2name=N'ImageID'
	EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Document File Type' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'VoucherPic', @level2type=N'COLUMN',@level2name=N'FileType'
	EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Image Title' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'VoucherPic', @level2type=N'COLUMN',@level2name=N'Title'
	EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Remark' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'VoucherPic', @level2type=N'COLUMN',@level2name=N'Remark'
	ALTER TABLE [dbo].[VoucherPic]  WITH CHECK ADD  CONSTRAINT [FK_pVoucherPic_pVoucher] FOREIGN KEY([Voucher])
	REFERENCES [dbo].[pVoucher] ([Voucher])
	ON UPDATE CASCADE
	ON DELETE CASCADE
	ALTER TABLE [dbo].[VoucherPic] CHECK CONSTRAINT [FK_pVoucherPic_pVoucher]
END
GO

