--Penambahan Table untuk Policy Deposit

IF  NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ACCDEPOSIT]') AND type in (N'U'))
begin
CREATE TABLE [dbo].[ACCDEPOSIT](
	[ANO] [int] NOT NULL,
	[REMARK] [varchar](50) NULL,
	[AMOUNT] [float] NULL,
	[Currency] [varchar](5) NULL,
	[Last_Opr] [varchar](50) NULL,
	[Last_Update] [smalldatetime] NULL,
 CONSTRAINT [I_ACCDEPOSIT] PRIMARY KEY CLUSTERED 
(
	[ANO] ASC
)WITH (PAD_INDEX  = OFF, STATISTICS_NORECOMPUTE  = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS  = ON, ALLOW_PAGE_LOCKS  = ON) ON [PRIMARY]
) ON [PRIMARY]
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Acceptance No. (see Acceptance)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'ACCDEPOSIT', @level2type=N'COLUMN',@level2name=N'ANO'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Remarks' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'ACCDEPOSIT', @level2type=N'COLUMN',@level2name=N'REMARK'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Deposit Amount' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'ACCDEPOSIT', @level2type=N'COLUMN',@level2name=N'AMOUNT'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Currency code' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'ACCDEPOSIT', @level2type=N'COLUMN',@level2name=N'Currency'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Last User Update' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'ACCDEPOSIT', @level2type=N'COLUMN',@level2name=N'Last_Opr'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Last Update' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'ACCDEPOSIT', @level2type=N'COLUMN',@level2name=N'Last_Update'
ALTER TABLE [dbo].[ACCDEPOSIT]  WITH CHECK ADD  CONSTRAINT [FK_ACCDEPOSIT_ACCEPTANCE] FOREIGN KEY([ANO])
REFERENCES [dbo].[ACCEPTANCE] ([ANO])
ON UPDATE CASCADE
ON DELETE CASCADE
ALTER TABLE [dbo].[ACCDEPOSIT] CHECK CONSTRAINT [FK_ACCDEPOSIT_ACCEPTANCE]
ALTER TABLE [dbo].[ACCDEPOSIT] ADD  CONSTRAINT [DF_ACCDEPOSIT_AMOUNT]  DEFAULT ((0)) FOR [AMOUNT]
END
