IF NOT EXISTS (SELECT * FROM ainfodet)
BEGIN

DROP TABLE [dbo].[AINFODET]

CREATE TABLE [dbo].[AINFODET](
	[ANO] [int] NOT NULL,
	[FLDID] [varchar](10) NOT NULL,
	[VALUEID] [varchar](15) NOT NULL,
	[REMARKS] [varchar](255) NULL,
	[MAXEXTPMT] [int] NULL,
	[TERMOFPMT] [int] NULL,
	[Currency] [varchar](10) NULL,
	[Limit] [float] NULL,
	[VPStart] [smalldatetime] NULL,
	[VPEnd] [smalldatetime] NULL,
	[AllowedF] [bit] NULL,
 CONSTRAINT [I_AINFODET] PRIMARY KEY CLUSTERED 
(
	[ANO] ASC,
	[FLDID] ASC,
	[VALUEID] ASC
)WITH (PAD_INDEX  = OFF, STATISTICS_NORECOMPUTE  = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS  = ON, ALLOW_PAGE_LOCKS  = ON)
)
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Ref to Acceptance' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'AINFODET', @level2type=N'COLUMN',@level2name=N'ANO'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Ref to TOC' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'AINFODET', @level2type=N'COLUMN',@level2name=N'FLDID'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Ref to TOC' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'AINFODET', @level2type=N'COLUMN',@level2name=N'VALUEID'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Value' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'AINFODET', @level2type=N'COLUMN',@level2name=N'REMARKS'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Maximal Extended Period (in Days)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'AINFODET', @level2type=N'COLUMN',@level2name=N'MAXEXTPMT'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Term Of Payment (in Days)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'AINFODET', @level2type=N'COLUMN',@level2name=N'TERMOFPMT'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Limit (Ex. Credit Limit)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'AINFODET', @level2type=N'COLUMN',@level2name=N'Limit'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Validity Period (Start)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'AINFODET', @level2type=N'COLUMN',@level2name=N'VPStart'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Validity Period (End)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'AINFODET', @level2type=N'COLUMN',@level2name=N'VPEnd'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Allow Selection (0 : No, 1 : Yes)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'AINFODET', @level2type=N'COLUMN',@level2name=N'AllowedF'
ALTER TABLE [dbo].[AINFODET]  WITH NOCHECK ADD  CONSTRAINT [AINFOAINFODET] FOREIGN KEY([ANO])
REFERENCES [dbo].[AINFO] ([ANO])
ON UPDATE CASCADE
ON DELETE CASCADE
ALTER TABLE [dbo].[AINFODET] CHECK CONSTRAINT [AINFOAINFODET]
ALTER TABLE [dbo].[AINFODET] ADD  CONSTRAINT [DF_AINFODET_AllowedF]  DEFAULT ((0)) FOR [AllowedF]
END
GO


