SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE Procedure [dbo].[BALANCE_ACCASS_ADJUSTMENT_REINSURANCE](@P_ANO integer)
as
Select AccAss.*, A1.PDate, A1.PPDate
From AccAss inner join Acceptance as A1 on (A1.ANO=AccAss.ANO) Left Join (Select Distinct Currency, Code, SDate, EDate, SANO, ExTreatyF from RCalc Where RCalc.ANO=@P_ANO) R on (R.Currency=AccAss.Currency and R.Code=AccAss.RCode and R.SDate=A1.PDate and R.EDate=A1.PPDate and R.SANO=A1.ANO), Acceptance as A2
Where A2.ANO=@P_ANO and A1.ANO<=A2.PANO and A1.OANO=A2.OANO and A1.ANO<>A2.ANO and AccAss.ANO=A1.ANO
and ((A2.PDate<=A1.PDate and A2.PPDate>=A1.PPDate and A2.AType='A' and AccAss.AdjustableF=1 and (AccAss.AdjMethod<>'OVERLIMIT' or AccAss.CAmount<>0) and A1.ANO not in (Select PANO from Acceptance A3 Where A3.PANO=A1.ANO and A3.Astatus<>'C' and A3.AType='A' and A3.ANO<>@P_ANO))
or (A2.AType='C' and A2.EMethod='A' and A1.PDate>=A2.PDate))
and ((R.ExTreatyF is null or R.ExTreatyF=0) or AccAss.Type not in ('CP','DC','QS','QP','S1','S2','S3','AF','XP'))
and AccAss.Type in ('CP','DC','QS','QP','S1','S2','S3','AF','XP','FO')


GO

