CREATE PROCEDURE [dbo].[CCalc01]  (@P_CNO AS INTEGER)  
AS  
SELECT   
      CCALC01A.CURRENCY,   
      CCALC01A.CODE,   
      CCALC01A.TOR,   
      SUM(CCALC01A.LOSS) AS LOSS,   
      SUM(CCALC01A.INDEMNITY) AS INDEMNITY,   
      SUM(CCALC01A.EDEDUCTIBLE) AS EDEDUCTIBLE,   
      SUM(CCALC01A.DEDUCTIBLE) AS DEDUCTIBLE,   
      SUM(CCALC01A.SALVAGE) AS SALVAGE  
FROM   
      CCALC01A(@P_CNO)  
GROUP BY   
      CCALC01A.CURRENCY,   
      CCALC01A.CODE,   
      CCALC01A.TOR  
  
GO

/****** Object:  StoredProcedure [dbo].[CCALC02]    Script Date: 3/1/2016 19:08:57 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO


CREATE PROCEDURE [dbo].[CCALC02] (@P_CNO as integer)
AS
SELECT
      CURRENCY,
      SUM(LOSS) AS LOSS,
      SUM(CLAIM) AS CLAIM,
      SUM(EDEDUCTIBLE) AS EDEDUCTIBLE,
      SUM(DEDUCTIBLE) AS DEDUCTIBLE,
      SUM(SALVAGE) AS SALVAGE,
      SUM(COST) AS COST,
      SUM(RCOST) AS RCOST,
      SUM(ECOST) AS ECOST,
      SUM(ERCOST) AS ERCOST,
      SUM(TCOST) AS TCOST,
      SUM(ETCOST) AS ETCOST,
      SUM(SUBROGATION) As SUBROGATION
FROM CCALC02A(@P_CNO)
GROUP BY CURRENCY

GO

