CREATE PROCEDURE [dbo].[CLAIM_ARRANGEMENT] (@PCNO AS INTEGER)  
AS  
SELECT DISTINCT Reinsurance.RID, Reinsurance.RType, Reinsurance.Limit, Reinsurance.Share, Reinsurance.Excess  
FROM Reinsurance, ReClass, Cover, Acceptance, Claim  
WHERE Claim.CNO=@PCNO And ACCEPTANCE.ANO=CLAIM.ANO And COVER.CNO=ACCEPTANCE.CNO 
And Reinsurance.RTYPE In ('X1','X2','X3','X4','X5','X6','X7','X8','X9','XX') 
And Reinsurance.RNO=ReClass.RNo And ReClass.TOC=COVER.TOC 
And Claim.LossDate between Reinsurance.SDate and Reinsurance.EDate


GO

/****** Object:  StoredProcedure [dbo].[Claim_Cession]    Script Date: 3/1/2016 19:11:32 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Claim_Cession] (@PCNO as integer, @pLDate as smalldatetime, @pRType as varchar(255)) 
AS 
SELECT (Case When ReClass.PriorityF=1 Then ReClass.PriorityF else Reinsurance.PriorityF end) as PriorityF, Reinsurance.RID, Reinsurance.RType, Reinsurance.Category, 
Reinsurance.Share, 
Case When Event.Category='E' and RECLASS.ELIMIT<>0 Then RECLASS.ELIMIT Else (Case WHEN RECLASS.Limit=0 THEN Reinsurance.Limit Else RECLASS.Limit end)End as Limit, 
Case When Event.Category='E' and RECLASS.EExcess<>0 Then RECLASS.EExcess Else (Case WHEN RECLASS.Excess=0 THEN Reinsurance.Excess Else RECLASS.Excess end) End as Excess, 
Reinsurance.ExcessType, 
RECLASS.CessionF , RECLASS.AssessmentF, REINSURANCE.Deductible, REINSURANCE.A_Deductible, REINSURANCE.A_EDeductible, REINSURANCE.Aggregate, REINSURANCE.A_Aggregate, REINSURANCE.A_EAggregate 
FROM Claim 
Left Join Event On (Event.EventNo=Claim.EventNo) 
Inner Join Acceptance on (Acceptance.ANO=Claim.ANO) 
Inner Join Cover on (Cover.CNO=Acceptance.CNO) 
Inner Join RArrHeader on (RArrHeader.ANO=Claim.ANO) 
Inner Join Reinsurance on (Reinsurance.RTYPE=@pRType and @pLDate Between Reinsurance.SDate And Reinsurance.EDate) 
Inner Join ReClass on (ReClass.RNO=Reinsurance.RNO and ReClass.TOC=Claim.TOC) 
Left Join RePolicy on (RePolicy.RNO=Reinsurance.RNO) 
WHERE Claim.CNO=@PCNO 
and RArrHeader.EXOLF=0        --Not Exclude XOL 
and (coalesce(Event.EventNo,'')<>'' or ReClass.EventF=0) and (Event.Category='E' or Reinsurance.Category<>'E') 
And Reinsurance.Category<>'S' --Not Shortfall Surplus 
And (coalesce(RePolicy.ID,'')='' or  coalesce(RePolicy.ID,'')=Cover.PHolder) 
Order By coalesce(RePolicy.ID,'') Desc, (Case When ReClass.PriorityF=1 Then ReClass.PriorityF else Reinsurance.PriorityF end) Desc 
 
 

GO

/****** Object:  StoredProcedure [dbo].[Claim_Cession_XOLShortFall]    Script Date: 3/1/2016 19:11:48 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


Create PROCEDURE [dbo].[Claim_Cession_XOLShortFall] (@PCNO as integer, @pRDate as smalldatetime, @pRType as varchar(255))  
AS  
SELECT DISTINCT (Case When ReClass.PriorityF=1 Then ReClass.PriorityF else Reinsurance.PriorityF end) as PriorityF, Reinsurance.RID, Reinsurance.RType, Reinsurance.Category,  
Case RECLASS.Limit  
 WHEN 0 then Reinsurance.Limit  
 Else RECLASS.Limit  
end as limit,  
Reinsurance.Share,  
Case RECLASS.Excess  
 WHEN 0 then Reinsurance.Excess  
 Else RECLASS.Excess  
end as Excess,  
RECLASS.CessionF , RECLASS.AssessmentF, REINSURANCE.Deductible, REINSURANCE.A_Deductible, REINSURANCE.A_EDeductible, REINSURANCE.Aggregate, REINSURANCE.A_Aggregate, REINSURANCE.A_EAggregate  
FROM Reinsurance, ReClass, Claim, RArrHeader  
WHERE Claim.CNO=@PCNO And Reinsurance.RTYPE=@pRType  
And RArrHeader.ANO=Claim.ANO and RArrHeader.EXOLF=0  
And Reinsurance.RNO=ReClass.RNo And Reinsurance.SDate<=@pRDate And Reinsurance.EDate>=@pRDate  
And ReClass.TOC=CLAIM.TOC And Reinsurance.Category='S'
Order By (Case When ReClass.PriorityF=1 Then ReClass.PriorityF else Reinsurance.PriorityF end) Desc  
                  

GO

