SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[CLItemLossTo] (@P_CNO as integer, @P_Currency as varchar(255)) 
AS 
 
SELECT CNO, PAYMENT, CURRENCY, RefNo, SUM(CLAIM) AS CLAIM, SUM(TAX) AS TAX, SUM(DEDUCTIBLE) AS DEDUCTIBLE 
FROM 
( 
SELECT CLLOSS.CNO, CLLOSS.Payment, CLLOSS.CURRENCY, CLLOSS.RefNo, 
Max( 
CASE 
WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN CLLOSS.AMOUNT 
ELSE (CLLOSS.DECLARED/CLLOSS.VAR) * CLLOSS.AMOUNT 
END 
) as CLAIM, 
Max( 
CASE 
WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN CLLOSS.TAX 
ELSE (CLLOSS.DECLARED/CLLOSS.VAR) * CLLOSS.TAX 
END 
) as TAX, 
Max( 
CASE 
WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN CLLOSS.AMOUNT 
ELSE (CLLOSS.DECLARED/CLLOSS.VAR) * CLLOSS.AMOUNT 
END*(RCOVER.COSHARE)/100 
) as DEDUCTIBLE 
From CLLOSS, CLAIM, RCOVER, ICALC, ACCEPTANCE, cover, COL 
WHERE CLLOSS.CNO=@P_CNO AND CLLOSS.CURRENCY=@P_CURRENCY AND CLAIM.CNO=CLLOSS.CNO 
AND CLLOSS.STATUS='P' 
AND ACCEPTANCE.ANO=CLAIM.ANO AND COVER.CNO=ACCEPTANCE.CNO AND RCOVER.ANO=ACCEPTANCE.ANO 
AND ((RCOVER.SDATE<=CLAIM.LOSSDATE AND ACCEPTANCE.ExclusiveF=1) or ((RCOVER.SDATE<CLAIM.LOSSDATE or (RCOVER.SDATE=CLAIM.LOSSDATE AND '12:00'<=Claim.LossTime)) AND ACCEPTANCE.ExclusiveF=0)) 
AND ((dbo.fn_Get_ExtPeriodDate(ACCEPTANCE.ExtPeriod, ACCEPTANCE.ExtPeriodInDaysF, RCOVER.EDATE)>CLAIM.LOSSDATE AND ACCEPTANCE.ExclusiveF=1) or ((dbo.fn_Get_ExtPeriodDate(ACCEPTANCE.ExtPeriod, ACCEPTANCE.ExtPeriodInDaysF, RCOVER.EDATE)>CLAIM.LOSSDATE or (dbo.fn_Get_ExtPeriodDate(ACCEPTANCE.ExtPeriod, ACCEPTANCE.ExtPeriodInDaysF, RCOVER.EDATE)=CLAIM.LOSSDATE AND '12:00'>Claim.LossTime)) AND ACCEPTANCE.ExclusiveF=0)) 
AND ICALC.ANO=RCOVER.ANO AND ICALC.CODE=RCOVER.CODE AND ICALC.SDATE=RCOVER.SDATE 
AND ICALC.INO=CLLOSS.INO 
AND COL.COL=CLAIM.COL AND COL.TOR=ICALC.TOR 
Group By CLLOSS.CNO, CLLOSS.INO, CLLOSS.PAYMENT, CLLOSS.NOC, CLLOSS.Currency, CLLOSS.RefNo 
) CLLOSS 
 
GROUP BY CNO, PAYMENT, [CURRENCY], RefNo 
 
 

GO

