CREATE  PROCEDURE [dbo].[CLVIEW05b] (@PCNO AS INTEGER) 
AS
SELECT CCALC.*, CCALC.CLAIM-CCALC.DEDUCTIBLE-CCALC.SALVAGE+CCALC.COST-CCALC.SUBROGATION AS TOTAL
FROM CCALC
