/****** Object:  StoredProcedure [dbo].[PointRewardRenewal_Process]    Script Date: 3/1/2016 22:36:01 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

Create Procedure [dbo].[PointRewardRenewal_Process](@P_CardID as varchar(20), @P_SDate as Smalldatetime, @P_EDate as smalldatetime)  
as  
Select   
OneCardH.CardID,   
Case When Acceptance.LANO=-1 or Cover.OpenFlag=0 Then 'Policy' else 'Certificate' end as DocType,   
Case When Acceptance.LANO=-1 or Cover.OpenFlag=0 Then Acceptance.PolicyNo else Acceptance.PolicyNo+'-'+Acceptance.CertificateNo end as DocNo,  
Max(Acceptance.ADate) as Date,  
Max(Acceptance.Renewal) as RYear,  
Max(coalesce(PRewardR.RPP, PRewardD.RPP)) as RPP,  
Max(coalesce(PRewardR.RPC, PRewardD.RPC)) as RPC  
from Acceptance  
inner join Cover on (Cover.CNO=Acceptance.CNO)  
inner join TOC on (TOC.TOC=Cover.TOC)  
inner join OneCardD on (OneCardD.ID=Cover.PHolder)  
inner join OneCardH on (OneCardH.CardID=OneCardD.CardID and (OneCardH.CardID=@P_CardID or @P_CardID='<All>'))  
Inner join PRewardD on (PRewardD.PYear=Year(@P_SDate) and (PRewardD.TOC='<All>' or PRewardD.TOC=Cover.TOC))  
Left  Join PRewardR on (PRewardR.PYear=PRewardD.PYear and PRewardR.TOC=PRewardD.TOC and PRewardR.TOR=PRewardD.TOR and PRewardR.RYear=Acceptance.Renewal)  
Where ((Acceptance.ANO<>Acceptance.LANO  and Cover.OpenFlag=1) or (Acceptance.LANO=-1))
and ((Acceptance.EDate Between @P_SDate and @P_EDate))
and Acceptance.Renewal<>0 and Acceptance.AType='N' and Acceptance.AStatus not in ('W','T') and Cover.CStatus<>'C'  
and PRewardD.TOR in (Select '<All>' union all Select RCalc.TOR from RCalc Where RCalc.ANO=Acceptance.ANO)  
Group By   
OneCardH.CardID,   
Case When Acceptance.LANO=-1 or Cover.OpenFlag=0 Then 'Policy' else 'Certificate' end,   
Case When Acceptance.LANO=-1 or Cover.OpenFlag=0 Then Acceptance.PolicyNo else Acceptance.PolicyNo+'-'+Acceptance.CertificateNo end  

Union All

Select
OneCardH.CardID,   
Case When Acceptance.LANO=-1 or Cover.OpenFlag=0 Then 'Policy' else 'Certificate' end as DocType,   
Case When Acceptance.LANO=-1 or Cover.OpenFlag=0 Then Acceptance.PolicyNo else Acceptance.PolicyNo+'-'+Acceptance.CertificateNo end as DocNo,  
Max(Acceptance.ADate) as Date,  
Max(Acceptance.Renewal) as RYear,  
Max(coalesce(PRewardR.RPP, PRewardD.RPP)) as RPP,  
Max(coalesce(PRewardR.RPC, PRewardD.RPC)) as RPC  
from Acceptance  
inner join Cover on (Cover.CNO=Acceptance.CNO)  
inner join TOC on (TOC.TOC=Cover.TOC)  
inner join OneCardD on (OneCardD.ID=Cover.PHolder)  
inner join OneCardH on (OneCardH.CardID=OneCardD.CardID and (OneCardH.CardID=@P_CardID or @P_CardID='<All>'))  
Inner join PRewardD on (PRewardD.PYear=Year(@P_SDate) and (PRewardD.TOC='<All>' or PRewardD.TOC=Cover.TOC))  
Left  Join PRewardR on (PRewardR.PYear=PRewardD.PYear and PRewardR.TOC=PRewardD.TOC and PRewardR.TOR=PRewardD.TOR and PRewardR.RYear=Acceptance.Renewal)  
Where (Acceptance.ANO=Acceptance.LANO and Cover.OpenFlag=0) 
and ((Acceptance.EDate Between @P_SDate and @P_EDate))
and Acceptance.Renewal<>0 and Acceptance.AType='N' and Acceptance.AStatus not in ('W','T') and Cover.CStatus<>'C'  
and PRewardD.TOR in (Select '<All>' union all Select RCalc.TOR from RCalc Where RCalc.ANO=Acceptance.ANO)  
Group By   
OneCardH.CardID,   
Case When Acceptance.LANO=-1 or Cover.OpenFlag=0 Then 'Policy' else 'Certificate' end,   
Case When Acceptance.LANO=-1 or Cover.OpenFlag=0 Then Acceptance.PolicyNo else Acceptance.PolicyNo+'-'+Acceptance.CertificateNo end  
GO


 

/****** Object:  StoredProcedure [dbo].[ProcessFAData]    Script Date: 3/1/2016 22:38:38 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[ProcessFAData](@PBranch varchar(10),@PSDate smalldatetime, @PEDate smalldatetime)    
AS    
begin    
    
set nocount on    
select * into #Voucher from Voucher Where Voucher.Branch=@PBranch and Voucher.Date Between @PSDate and @PEDate    
    
Create Table #SL(Voucher varchar(20), Nominal float)    
    
insert into #SL select Voucher.Voucher, sum(Case When Voucher.DebtorF=1 then SL.Nominal_OC else -SL.Nominal_OC end) as Nominal from nVoucher Voucher, SL_Payment() SL, #Voucher  Where #Voucher.Voucher=SL.Voucher and SL.Doc_No=Voucher.Voucher and Sl.PaymentF=1 Group by Voucher.Voucher    
    
Update Voucher set Voucher.Payment_CC=Voucher.Payment_CC+#SL.Nominal from nVoucher Voucher, #SL Where Voucher.Voucher=#SL.Voucher    
    
-- RV vs PV    
insert into #SL Select Voucher.Voucher, sum(SL.Nominal_OC) as Nominal from pSL SL, pVoucher Voucher, #Voucher VoucherP Where Voucher.Voucher=SL.Doc_No and SL.PaymentF=1 and VoucherP.Voucher=SL.Voucher and VoucherP.SL_Cat in ('P') and VoucherP.DebtorF<>Voucher.DebtorF Group By Voucher.Voucher    
    
Update Voucher Set Payment_CC=Payment_CC+SL.Nominal from #SL SL, pVoucher Voucher Where SL.Voucher=Voucher.Voucher and Voucher.SL_Cat='P'     
    
delete from #SL    
    
insert into #SL Select Voucher.Voucher, sum(SL.Nominal_OC) as Nominal from pSL SL, pVoucher Voucher, #Voucher VoucherP Where Voucher.Voucher=SL.Doc_No and SL.PaymentF=1 and VoucherP.Voucher=SL.Voucher and VoucherP.SL_Cat in ('P') and VoucherP.DebtorF=Voucher.DebtorF Group By Voucher.Voucher    
    
Update Voucher Set Payment_CC=Payment_CC-SL.Nominal from #SL SL, pVoucher Voucher Where SL.Voucher=Voucher.Voucher and Voucher.SL_Cat='P'     
    
delete from #SL    
    
    
    
-- Overpaid    
insert into #SL Select Voucher.Voucher, sum(SL.Nominal_OC) as Nominal from pSL SL, pVoucher Voucher, #Voucher VoucherP Where Voucher.Voucher=SL.Doc_No and SL.PaymentF=1 and VoucherP.Voucher=SL.Voucher and VoucherP.SL_Cat in ('O') and VoucherP.DebtorF=Voucher.DebtorF Group By Voucher.Voucher    
    
Update Voucher Set Payment_CC=Payment_CC+SL.Nominal from #SL SL, pVoucher Voucher Where Voucher.Voucher=SL.Voucher and Voucher.SL_Cat='P'    
    
delete from #SL    
    
insert into #SL Select Voucher.Voucher, sum(SL.Nominal_OC) as Nominal from pSL SL, pVoucher Voucher, #Voucher VoucherP Where Voucher.Voucher=SL.Doc_No and SL.PaymentF=1 and VoucherP.Voucher=SL.Voucher and VoucherP.SL_Cat in ('O') and VoucherP.DebtorF<>Voucher.DebtorF Group By Voucher.Voucher    
    
Update Voucher Set Payment_CC=Payment_CC-SL.Nominal from #SL SL, pVoucher Voucher Where Voucher.Voucher=SL.Voucher and Voucher.SL_Cat='P'    
    
delete from #SL    
    
    
-- Referenced by    
-- Overbooking    
insert into #SL Select Voucher.Voucher, sum(SL.Nominal) as Nominal from pSL SL, pVoucher Voucher, #Voucher VoucherP Where VoucherP.Voucher=SL.Voucher and VoucherP.RefNo=Voucher.Voucher and VoucherP.SL_Cat='B' and VoucherP.DebtorF=Voucher.DebtorF Group By Voucher.Voucher    
    
Update Voucher Set Payment_CC=Payment_CC+SL.Nominal from #SL SL, pVoucher Voucher Where Voucher.Voucher=SL.Voucher and Voucher.SL_Cat='P'     
    
delete from #SL    
    
insert into #SL Select Voucher.Voucher, sum(SL.Nominal) as Nominal from pSL SL, pVoucher Voucher, #Voucher VoucherP Where VoucherP.Voucher=SL.Voucher and VoucherP.RefNo=Voucher.Voucher and VoucherP.SL_Cat='B' and VoucherP.DebtorF<>Voucher.DebtorF Group By Voucher.Voucher    
    
Update Voucher Set Payment_CC=Payment_CC-SL.Nominal from #SL SL, pVoucher Voucher Where Voucher.Voucher=SL.Voucher and Voucher.SL_Cat='P'     
    
delete from #SL    
    
--Adjustment Payment    
insert into #SL Select Voucher.Voucher, sum(SL.Nominal) as Nominal from pSL SL, pVoucher Voucher, #Voucher VoucherP Where VoucherP.Voucher=SL.Voucher and VoucherP.RefNo=Voucher.Voucher and VoucherP.SL_Cat='A' and VoucherP.DebtorF=Voucher.DebtorF Group By Voucher.Voucher    
    
Update Voucher Set Payment_CC=Payment_CC+SL.Nominal from #SL SL, pVoucher Voucher Where Voucher.Voucher=SL.Voucher and Voucher.SL_Cat='P'     
    
delete from #SL    
    
insert into #SL Select Voucher.Voucher, sum(SL.Nominal) as Nominal from pSL SL, pVoucher Voucher, #Voucher VoucherP Where VoucherP.Voucher=SL.Voucher and VoucherP.RefNo=Voucher.Voucher and VoucherP.SL_Cat='A' and VoucherP.DebtorF<>Voucher.DebtorF Group By Voucher.Voucher    
    
Update Voucher Set Payment_CC=Payment_CC-SL.Nominal from #SL SL, pVoucher Voucher Where Voucher.Voucher=SL.Voucher and Voucher.SL_Cat='P'     
    
delete from #SL    
    
--Adjustment via Overbooking    
    
insert into #SL Select Voucher.Voucher, sum(SL.Nominal) as Nominal from pSL SL, pVoucher Voucher, #Voucher VoucherP, Voucher VoucherO Where VoucherP.Voucher=SL.Voucher and VoucherP.RefNo=VoucherO.Voucher and VoucherO.RefNo=Voucher.Voucher and VoucherP.SL_Cat='A' and VoucherP.DebtorF=Voucher.DebtorF Group By Voucher.Voucher    
    
Update Voucher Set Payment_CC=Payment_CC+SL.Nominal from #SL SL, pVoucher Voucher Where Voucher.Voucher=SL.Voucher and Voucher.SL_Cat='P'    
    
delete from #SL    
    
insert into #SL Select Voucher.Voucher, sum(SL.Nominal) as Nominal from pSL SL, pVoucher Voucher, #Voucher VoucherP, Voucher VoucherO Where VoucherP.Voucher=SL.Voucher and VoucherP.RefNo=VoucherO.Voucher and VoucherO.RefNo=Voucher.Voucher and VoucherP.SL_Cat='A' and VoucherP.DebtorF<>Voucher.DebtorF Group By Voucher.Voucher    
    
Update Voucher Set Payment_CC=Payment_CC-SL.Nominal from #SL SL, pVoucher Voucher Where Voucher.Voucher=SL.Voucher and Voucher.SL_Cat='P'    
    
delete from #SL    
  
--WithHolding Tax    
insert into #SL Select VoucherN.Voucher, sum(-SL.Nominal_OC) Nominal from #Voucher Voucher, nSL SL, VType, nVoucher VoucherN Where VoucherN.CreditorF=1 and VType.VType=Voucher.VType and Voucher.Voucher=SL.Voucher  and Voucher.SL_Cat='N' and VType.TaxF=1 and SL.PaymentF=1  and VoucherN.Voucher=SL.Doc_No and VoucherN.SL_Cat='N' Group By VoucherN.Voucher  
Update nVoucher Set TaxPayment_CC= TaxPayment_CC+SL.Nominal from #SL SL, nVoucher Where SL.Voucher=nVoucher.Voucher  
Delete from #SL  
  
insert into #SL Select VoucherN.Voucher, sum(SL.Nominal_OC) Nominal from #Voucher Voucher, nSL SL, VType, nVoucher VoucherN Where VoucherN.DebtorF=1 and VType.VType=Voucher.VType and Voucher.Voucher=SL.Voucher  and Voucher.SL_Cat='N' and VType.TaxF=1 and SL.PaymentF=1  and VoucherN.Voucher=SL.Doc_No and VoucherN.SL_Cat='N' Group By VoucherN.Voucher  
Update nVoucher Set TaxPayment_CC= TaxPayment_CC+SL.Nominal from #SL SL, nVoucher Where SL.Voucher=nVoucher.Voucher  
Delete from #SL  
    
select SL.Doc_No as Voucher, Max(#Voucher.Date) as PDate into #SLVoucher from #Voucher, SL Where SL.PaymentF=1 and SL.Voucher=#Voucher.Voucher Group By SL.Doc_No    
    
Update Voucher Set PDate=#SLVoucher.PDate from pVoucher Voucher, #SLVoucher Where Voucher.Voucher=#SLVoucher.Voucher    
Update Voucher Set PDate=#SLVoucher.PDate from nVoucher Voucher, #SLVoucher Where Voucher.Voucher=#SLVoucher.Voucher    
    
drop table #SLVoucher    
drop table #SL    
drop table #Voucher    
    
end    
    
  

GO


 
