/****** Object:  StoredProcedure [dbo].[QACCDOCLIST]    Script Date: 3/1/2016 22:45:04 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[QACCDOCLIST](@P_ANO integer) 
as 
Select * 
from 
( 
select Cast(coalesce(ACCDOCLIST.AvailableF, 0) as bit) as ProcessFlag, PDOCLIST.DocType, coalesce(ACCDOCLIST.Description, PDOCLIST.Description) as Description, coalesce(ACCDOCLIST.AvailableF, 0) as AvailableF, cast(coalesce(DOCTYPE.CollectionF,0) as Bit) as CollectionF, ACCDOCLIST.RECDATE 
from ACCEPTANCE INNER JOIN COVER ON (ACCEPTANCE.ANO=@P_ANO AND COVER.CNO=ACCEPTANCE.CNO) INNER JOIN PDOCLIST ON (PDOCLIST.TOC=COVER.TOC) Left join DOCTYPE on (DOCTYPE.DOCTYPE=PDOCLIST.DOCTYPE) 
Left Join ACCDOCLIST on (ACCDOCLIST.ANO=@P_ANO and ACCDOCLIST.DOCTYPE=PDOCLIST.DOCTYPE) 
 
Union All 
 
select Cast(coalesce(ACCDOCLIST.AvailableF, 0) as bit) as ProcessFlag, ACCDOCLIST.DocType, ACCDOCLIST.Description, ACCDOCLIST.AvailableF, cast(coalesce(DOCTYPE.CollectionF,0) as Bit) as CollectionF, ACCDOCLIST.RECDATE 
from ACCDOCLIST Left Join DOCTYPE on (DOCTYPE.DOCTYPE=ACCDOCLIST.DOCTYPE) 
Where ACCDOCLIST.ANO=@P_ANO 
AND NOT EXISTS (Select PDOCLIST.DOCTYPE from PDOCLIST, COVER, ACCEPTANCE Where PDOCLIST.DOCTYPE=ACCDOCLIST.DOCTYPE AND ACCEPTANCE.ANO=@P_ANO AND COVER.CNO=ACCEPTANCE.CNO AND PDOCLIST.TOC=COVER.TOC) 
) ACCDOCLIST 
Order By ACCDOCLIST.DOCTYPE 
 
 

GO


 

/****** Object:  StoredProcedure [dbo].[QACCDOCSTAT]    Script Date: 3/1/2016 22:45:16 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QACCDOCSTAT] (@PANO AS INTEGER) 
AS 
Select cast(Case When A.StatID is not Null Then 1 else 0 end as Bit) as ProcessFlag, D.StatID, Coalesce(D.Description, '') as Description, Coalesce(A.Remarks, '') as Remarks, 
Coalesce(A.CheckF, 0) as CheckF, 
Coalesce(A.ActionBy, '') as ActionBy,   Coalesce(A.ActionDate, '') as ActionDate, Coalesce(A.ActionTime, '') as ActionTime, Coalesce(A.AcceptedBy, '') as AcceptedBy, Coalesce(A.AcceptedDate, '') as AcceptedDate, 
Coalesce(A.AcceptedTime, '') as AcceptedTime, D.AllowedF, 
Coalesce(A.Last_Opr, '') as Last_OPR, Coalesce(A.Last_Update, '') as Last_Update 
from Docstat D Left join AccDocStat A on (D.StatID=A.StatID and A.ANO=@PANO) 
Where (D.AllowedF = 1 Or A.StatID Is Not null) 
and coalesce(D.Purpose,'POLICY')='POLICY' 
 
 

GO


 
