/****** Object:  StoredProcedure [dbo].[QAccumulation]    Script Date: 3/1/2016 22:48:48 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QAccumulation] (@P_REGID as varchar(10), @P_FLDID as varchar(255), @P_VALUEID as varchar(255), @P_RTYPE as varchar(10))      
AS      
Declare @P_Amount as float    
Declare @P_TSI as float    
Declare @P_RYear as int    
Declare @P_REALLOCF as bit    
  
if @P_FLDID<>'' and @P_VALUEID<>''   
Begin  
 SELECT @P_Amount=SUM(AMOUNT), @P_TSI=SUM(TSI), @P_RYear=MAX(RYEAR), @P_REALLOCF=MAX(Cast(REALLOCF as int))    
 From AccRegDet      
 WHERE ACCREGDET.REGID=@P_REGID AND ACCREGDET.FLDID=@P_FLDID AND ACCREGDET.VALUEID=@P_VALUEID AND ACCREGDET.RTYPE=@P_RTYPE AND ACCREGDET.TSI<>0      
     
 if @P_TSI is null     
  Select @P_Amount=0, @P_TSI=sum(R.TAmount), @P_RYear=MAX(YEAR(R.RDate)), @P_REALLOCF=0    
  from RArrHeader R, Acceptance A    
  Where A.ANO=R.ANO and R.Status='A' and A.RegID=@P_REGID and A.FLDID=@P_FLDID and A.ValueID=@P_VALUEID    
End     
Select @P_Amount as Amount , @P_TSI as TSI, @P_RYear as RYear, @P_REALLOCF as REALLOCF            


GO


 
