CREATE PROCEDURE [dbo].[QCheck_Coverage] (@P_ANO as integer) 
AS
SELECT 'Interest' as Type, ICover.Remark
FROM 	ICover
WHERE ICover.ANO=@P_ANO and ICover.TOI not in 
(Select PClass.TOI  from RateCov, RCover, PClass Where RateCov.Code=RCover.Code and PClass.TOI=ICover.TOI and PClass.TOR=RateCov.TOR and RCover.ANO=@P_ANO)

union all

SELECT 'Risk' as Type, RCover.Remark
FROM 	RCover
WHERE RCover.ANO=@P_ANO and RCover.Code not in 
(Select RateCov.Code  from RateCov, ICover, PClass Where ICover.SI<>0 and RateCov.Code=RCover.Code and PClass.TOI=ICover.TOI and PClass.TOR=RateCov.TOR and ICover.ANO=@P_ANO)


