CREATE PROCEDURE [dbo].[QCLAASS_3](@P_CNO int,@P_RefNo varchar(20), @P_Type varchar(255),@P_ID varchar(255),@P_CCY varchar(255)) 
as 
SELECT  ClaAss.CNO AS CNO, 
ClaAss.RefNo, 
ClaAss.Date, 
ClaAss.BillDate, 
ClaAss.TOC, 
ClaAss.ClaimNo, 
ClaAss.Remarks, 
ClaAss.ID, 
Profile.Name, 
ClaAss.Type, 
currency_oc, 
sum(case when ClaAss.code='A' then Amount_OC else 0 end) AS Claim, 
sum(case when ClaAss.code='E' then Amount_OC else 0 end) AS Deductible, 
sum(case when ClaAss.code='L' then Amount_OC else 0 end) AS Cost, 
sum(case when ClaAss.code='S' then Amount_OC else 0 end) AS Salvage, 
sum(case when ClaAss.code='R' then Amount_OC else 0 end) AS Subrogation, 
sum(case when ClaAss.code='P' then Amount_OC else 0 end) AS Premium, 
sum(case when ClaAss.code='I' then Amount_OC else 0 end) AS Adjustment, 
(ClaAss.Posted) AS Posted 
FROM  ClaAss, Profile 
WHERE  Profile.ID=ClaAss.ID 
And ClaAss.CNO=@P_CNO 
And ClaAss.RefNo=@P_RefNo 
and ClaAss.Type=@P_Type 
and ClaAss.ID=@P_ID 
and ClaAss.Currency_OC=@P_CCY 
GROUP BY ClaAss.CNO, ClaAss.RefNo, ClaAss.Date, ClaAss.BillDate, ClaAss.TOC, ClaAss.ClaimNo, ClaAss.Remarks, ClaAss.ID, Profile.Name, ClaAss.Type, Currency_OC,(ClaAss.Posted) 
 
 

GO


 

