CREATE PROCEDURE [dbo].[QCLACC_6] (@P_ANO as int, @P_CTLF as bit=1) 
AS 
SELECT C1.ClaimNo, C1.RegDate, C1.LossDate, C2.CTLF 
FROM Claim C1, ClLoss C2, Acceptance A1, Acceptance A2 
WHERE A2.ANO=@P_ANO and A1.OANO=A2.OANO and A1.ANO=C1.ANO and C2.CNO=C1.CNO and C1.CType<>'C' and (C1.CSTATUS IN ('R','P','T','A') OR C1.PCSTATUS IN ('A')) 
and (@P_CTLF=0 or C2.CTLF=@P_CTLF) and C1.TBAF_1=0 and C1.TBAF_2=0 
Order by C1.LossDate 
 
 
 

GO


 

