CREATE PROCEDURE [dbo].[QCLAREGAMOUNT_EX] (@PCNO AS integer) 
AS
SELECT CARRHEADER.RAMOUNT AS AMOUNT, CARRHEADER.ERAMOUNT AS EAMOUNT
FROM CARRHEADER, CLAIM, CLAREGDET
WHERE CLAIM.CNO=@PCNO And ((CARRHEADER.CNO=CLAIM.CNO) Or (CARRHEADER.CNO=CLAIM.PCNO)) And CARRHEADER.STATUS='A' And CLAREGDET.REGNO=CARRHEADER.RREGNO




GO


 
