CREATE PROCEDURE [dbo].[QCLFAC02] (@P_CNO as Integer, @P_FID as VARCHAR(20)) 
AS 
SELECT Distinct CLAIM.CNO, FDEDUCTIBLE.TOR, FDEDUCTIBLE.REMARKS, FDEDUCTIBLE.CURRENCY, FDEDUCTIBLE.DCODE 
From CLAIM, FDEDUCTIBLE, RArrDet, COL 
Where RArrDet.ANO = FDEDUCTIBLE.ANO AND RARRDET.FID=FDEDUCTIBLE.FID AND RARRDET.ORIGINALF=0 
AND FDEDUCTIBLE.ANO=CLAIM.ANO 
AND CLAIM.CNO=@P_CNO 
AND FDEDUCTIBLE.FID=@P_FID 
AND COL.COL=CLAIM.COL AND FDEDUCTIBLE.TOR=COL.TOR 
 
 
 

GO


 

/****** Object:  StoredProcedure [dbo].[QCLFAC02_1]    Script Date: 3/1/2016 23:29:37 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QCLFAC02_1] (@P_CNO as Integer, @P_FID as VARCHAR(20), @P_DCODE as VARCHAR(20))  
AS  
SELECT DISTINCT FDEDUCTIBLE.DCODE, FDEDUCTIBLE.REMARKS, FDEDUCTIBLE.CURRENCY, CLAIM.CNO  
From CLAIM, FDEDUCTIBLE, RArrDet  
Where RArrDet.ANO = FDEDUCTIBLE.ANO  
 AND RARRDET.FID=FDEDUCTIBLE.FID  
 AND RARRDET.ORIGINALF=0  
 AND FDEDUCTIBLE.ANO=CLAIM.ANO  
 AND CLAIM.CNO=@P_CNO  
 AND FDEDUCTIBLE.FID=@P_FID
 AND FDEDUCTIBLE.DCODE=@P_DCODE  
 AND 1 in (SELECT 1 FROM COL WHERE COL.COL=CLAIM.COL AND COL.TOR=FDEDUCTIBLE.TOR) 


GO

 

