CREATE PROCEDURE [dbo].[QCLLOSS](@PCNO AS INTEGER, @PINO AS INTEGER,@P_ID AS VARCHAR(255), @P_NOC as VARCHAR(10),@P_Currency as VARCHAR(5), @P_RefNO as varchar(20) = '%') 
AS 
SELECT * 
FROM CLLOSS 
WHERE CLLOSS.CNO=@PCNO AND CLLOSS.INO=@PINO and CLLOSS.PAYMENT=@P_ID and CLLOSS.NOC=@P_NOC and CLLOSS.CURRENCY=@P_Currency and CLLOSS.REFNO like @P_RefNo 
 
 

GO


 

/****** Object:  StoredProcedure [dbo].[QCLLOSS_1]    Script Date: 3/1/2016 23:30:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO 
CREATE PROCEDURE [dbo].[QCLLOSS_1] (@PCNO AS INTEGER) 
AS
SELECT CLLOSS.Currency, sum(CLLOSS.declared) AS declared, sum(CLLOSS.Amount) AS Amount
FROM CLLOSS
WHERE CLLOSS.CNO=@PCNO
GROUP BY CLLOSS.Currency
 
GO


 
