 COB.FLDID12, COB.FLDTAG12, GENHTAB_12.FLDTAB AS FLDTAB12, GENHTAB_12.FLDCOM AS FLDCOM12, GENHTAB_12.FLDDFORMAT AS FLDDFORMAT12, GENHTAB_12.FLDIFORMAT AS FLDIFORMAT12, GENHTAB_12.FLDTYPE AS FLDTYPE12, GENHTAB_12.SUBLINKF AS SUBLINKF12,  GENHTAB_12.FLDSEARCH AS FLDSEARCH12, GENHTAB_12.FLDCRITERIA AS FLDCRITERIA12,
 COB.FLDID13, COB.FLDTAG13, GENHTAB_13.FLDTAB AS FLDTAB13, GENHTAB_13.FLDCOM AS FLDCOM13, GENHTAB_13.FLDDFORMAT AS FLDDFORMAT13, GENHTAB_13.FLDIFORMAT AS FLDIFORMAT13, GENHTAB_13.FLDTYPE AS FLDTYPE13, GENHTAB_13.SUBLINKF AS SUBLINKF13,  GENHTAB_13.FLDSEARCH AS FLDSEARCH13, GENHTAB_13.FLDCRITERIA AS FLDCRITERIA13,
 COB.FLDID14, COB.FLDTAG14, GENHTAB_14.FLDTAB AS FLDTAB14, GENHTAB_14.FLDCOM AS FLDCOM14, GENHTAB_14.FLDDFORMAT AS FLDDFORMAT14, GENHTAB_14.FLDIFORMAT AS FLDIFORMAT14, GENHTAB_14.FLDTYPE AS FLDTYPE14, GENHTAB_14.SUBLINKF AS SUBLINKF14,  GENHTAB_14.FLDSEARCH AS FLDSEARCH14, GENHTAB_14.FLDCRITERIA AS FLDCRITERIA14,
 COB.FLDID15, COB.FLDTAG15, GENHTAB_15.FLDTAB AS FLDTAB15, GENHTAB_15.FLDCOM AS FLDCOM15, GENHTAB_15.FLDDFORMAT AS FLDDFORMAT15, GENHTAB_15.FLDIFORMAT AS FLDIFORMAT15, GENHTAB_15.FLDTYPE AS FLDTYPE15, GENHTAB_15.SUBLINKF AS SUBLINKF15,  GENHTAB_15.FLDSEARCH AS FLDSEARCH15, GENHTAB_15.FLDCRITERIA AS FLDCRITERIA15
From
 COBEXT COB
 LEFT OUTER JOIN GENHTAB as GENHTAB_1 ON COB.FLDID1 = GENHTAB_1.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_2 ON COB.FLDID2 = GENHTAB_2.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_3 ON COB.FLDID3 = GENHTAB_3.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_4 ON COB.FLDID4 = GENHTAB_4.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_5 ON COB.FLDID5 = GENHTAB_5.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_6 ON COB.FLDID6 = GENHTAB_6.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_7 ON COB.FLDID7 = GENHTAB_7.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_8 ON COB.FLDID8 = GENHTAB_8.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_9 ON COB.FLDID9 = GENHTAB_9.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_10 ON COB.FLDID10 = GENHTAB_10.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_11 ON COB.FLDID11 = GENHTAB_11.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_12 ON COB.FLDID12 = GENHTAB_12.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_13 ON COB.FLDID13 = GENHTAB_13.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_14 ON COB.FLDID14 = GENHTAB_14.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_15 ON COB.FLDID15 = GENHTAB_15.FLDID
WHERE  COB.COB = @P_COB





GO


 

