/****** Object:  StoredProcedure [dbo].[QFDEDUCTIBLE_CALC]    Script Date: 3/1/2016 23:43:17 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

 
CREATE PROCEDURE [dbo].[QFDEDUCTIBLE_CALC] (@P_CNO AS integer, @P_FID AS VARCHAR(20), @P_DCODE AS Varchar(10)) 
AS 
SELECT CNO, DEDCCY, DCODE,CURRENCY, MAX(REMARKS) AS REMARKS, MAX(FIXEDMIN) AS FIXEDMIN, MAX(FIXEDMAX) AS FIXEDMAX, SUM(DEDTSI) AS DEDTSI, SUM(DEDCL) AS DEDCL, SUM(LOSSESTIMATE) as LOSSESTIMATE, SUM(LOSSCLAIM) AS LOSSCLAIM 
From 
( 
SELECT CLAIM.CNO, 
CLLOSS.CURRENCY AS DEDCCY, 
FDEDUCTIBLE.DCODE, 
FDEDUCTIBLE.CURRENCY, 
CLLOSS.INO, 
MAX(FDEDUCTIBLE.REMARKS) AS REMARKS, 
MAX(FDEDUCTIBLE.FIXEDMIN) AS FIXEDMIN, 
MAX(FDEDUCTIBLE.FIXEDMAX) AS FIXEDMAX, 
MAX(Case When FDEDUCTIBLE.STRTSI='TSI' THEN PCALC.TSI ELSE CLLOSS.DECLARED END*FDEDUCTIBLE.PCTTSI*.01*CLLOSS.RATE) AS DEDTSI, 
SUM(CLLOSS.ESTIMATE*FDEDUCTIBLE.PCTCL*.01*(1-RCOVER.COSHARE/100)) AS DEDEST, 
SUM(CLLOSS.Amount * FDEDUCTIBLE.PCTCL * 0.01 * (1 - RCOVER.COSHARE / 100)) As DEDCL, 
SUM(CLLOSS.ESTIMATE) AS LOSSESTIMATE, 
SUM(CLLOSS.Amount) As LOSSCLAIM 
From CLAIM, ACCEPTANCE, FDEDUCTIBLE, CLLOSS, Col, PCLASS, RATECOV, RCOVER, RArrDet, PCALC 
Where 
CLAIM.CNO=@P_CNO 
AND ACCEPTANCE.ANO=CLAIM.ANO 
AND FDEDUCTIBLE.ANO=CLAIM.ANO 
AND FDEDUCTIBLE.DCODE=@P_DCODE 
AND FDEDUCTIBLE.FID=@P_FID 
AND RARRDET.ANO=FDEDUCTIBLE.ANO 
AND RARRDET.FID=@P_FID 
AND CLLOSS.CNO=CLAIM.CNO 
AND COL.COL=CLAIM.COL 
AND COL.TOR=FDEDUCTIBLE.TOR 
AND PCLASS.TOR=COL.TOR 
AND PCLASS.TOI=CLLOSS.TOI 
AND RCOVER.ANO=CLAIM.ANO 
AND ((RARRDET.SDATE<=CLAIM.LOSSDATE AND ACCEPTANCE.ExclusiveF=1) or ((RARRDET.SDATE<CLAIM.LOSSDATE or (RARRDET.SDATE=CLAIM.LOSSDATE AND '12:00'<=Claim.LossTime)) AND ACCEPTANCE.ExclusiveF=0)) 
AND ((dbo.fn_Get_ExtPeriodDate(ACCEPTANCE.ExtPeriod, ACCEPTANCE.ExtPeriodInDaysF, RARRDET.EDATE)>CLAIM.LOSSDATE AND ACCEPTANCE.ExclusiveF=1) or ((dbo.fn_Get_ExtPeriodDate(ACCEPTANCE.ExtPeriod, ACCEPTANCE.ExtPeriodInDaysF, RARRDET.EDATE)>CLAIM.LOSSDATE or (dbo.fn_Get_ExtPeriodDate(ACCEPTANCE.ExtPeriod, ACCEPTANCE.ExtPeriodInDaysF, RARRDET.EDATE)=CLAIM.LOSSDATE AND '12:00'>Claim.LossTime)) AND ACCEPTANCE.ExclusiveF=0)) 
AND ((RCOVER.SDATE<=CLAIM.LOSSDATE AND ACCEPTANCE.ExclusiveF=1) or ((RCOVER.SDATE<CLAIM.LOSSDATE or (RCOVER.SDATE=CLAIM.LOSSDATE AND '12:00'<=Claim.LossTime)) AND ACCEPTANCE.ExclusiveF=0)) 
AND ((dbo.fn_Get_ExtPeriodDate(ACCEPTANCE.ExtPeriod, ACCEPTANCE.ExtPeriodInDaysF, RCOVER.EDATE)>CLAIM.LOSSDATE AND ACCEPTANCE.ExclusiveF=1) or ((dbo.fn_Get_ExtPeriodDate(ACCEPTANCE.ExtPeriod, ACCEPTANCE.ExtPeriodInDaysF, RCOVER.EDATE)>CLAIM.LOSSDATE or (dbo.fn_Get_ExtPeriodDate(ACCEPTANCE.ExtPeriod, ACCEPTANCE.ExtPeriodInDaysF, RCOVER.EDATE)=CLAIM.LOSSDATE AND '12:00'>Claim.LossTime)) AND ACCEPTANCE.ExclusiveF=0)) 
AND RATECOV.CODE=RCOVER.CODE 
AND RATECOV.TOR=FDEDUCTIBLE.TOR 
AND PCALC.ANO=FDEDUCTIBLE.ANO 
AND PCALC.Currency=CLLOSS.Currency_OC 
AND (FDEDUCTIBLE.PCTTSI<>0 or FDEDUCTIBLE.PCTCL<>0 or FDEDUCTIBLE.FIXEDMIN<>0 or FDEDUCTIBLE.FIXEDMAX<>0) 
GROUP BY CLAIM.CNO, CLLOSS.CURRENCY, FDEDUCTIBLE.DCODE, FDEDUCTIBLE.CURRENCY, CLLOSS.INO 
) DEDUCTIBLE 
GROUP BY CNO, DEDCCY, DCODE,CURRENCY 
 
 

GO


 

