CREATE PROCEDURE [dbo].[QGENHTAB_GENHTAB] (@P_FLDID AS VARCHAR(10))  
AS  
SELECT  TOP 1  
 GENHTAB.SACCREG,  
 GENHTAB.FLDEDITABLE,
 GENHTAB.FLDID,   
 GENHTAB.FLDID1, GENHTAB.FLDTAG1, GENHTAB_1.FLDTAB AS FLDTAB1, GENHTAB_1.FLDCOM AS FLDCOM1, GENHTAB_1.FLDDFORMAT AS FLDDFORMAT1, GENHTAB_1.FLDIFORMAT AS FLDIFORMAT1, GENHTAB_1.FLDTYPE AS FLDTYPE1, GENHTAB_1.SUBLINKF AS SUBLINKF1,  
 GENHTAB.FLDID2, GENHTAB.FLDTAG2, GENHTAB_2.FLDTAB AS FLDTAB2, GENHTAB_2.FLDCOM AS FLDCOM2, GENHTAB_2.FLDDFORMAT AS FLDDFORMAT2, GENHTAB_2.FLDIFORMAT AS FLDIFORMAT2, GENHTAB_2.FLDTYPE AS FLDTYPE2, GENHTAB_2.SUBLINKF AS SUBLINKF2,  
 GENHTAB.FLDID3, GENHTAB.FLDTAG3, GENHTAB_3.FLDTAB AS FLDTAB3, GENHTAB_3.FLDCOM AS FLDCOM3, GENHTAB_3.FLDDFORMAT AS FLDDFORMAT3, GENHTAB_3.FLDIFORMAT AS FLDIFORMAT3, GENHTAB_3.FLDTYPE AS FLDTYPE3, GENHTAB_3.SUBLINKF AS SUBLINKF3,  
 GENHTAB.FLDID4, GENHTAB.FLDTAG4, GENHTAB_4.FLDTAB AS FLDTAB4, GENHTAB_4.FLDCOM AS FLDCOM4, GENHTAB_4.FLDDFORMAT AS FLDDFORMAT4, GENHTAB_4.FLDIFORMAT AS FLDIFORMAT4, GENHTAB_4.FLDTYPE AS FLDTYPE4, GENHTAB_4.SUBLINKF AS SUBLINKF4,  
 GENHTAB.FLDID5, GENHTAB.FLDTAG5, GENHTAB_5.FLDTAB AS FLDTAB5, GENHTAB_5.FLDCOM AS FLDCOM5, GENHTAB_5.FLDDFORMAT AS FLDDFORMAT5, GENHTAB_5.FLDIFORMAT AS FLDIFORMAT5, GENHTAB_5.FLDTYPE AS FLDTYPE5, GENHTAB_5.SUBLINKF AS SUBLINKF5,  
 GENHTAB.FLDID6, GENHTAB.FLDTAG6, GENHTAB_6.FLDTAB AS FLDTAB6, GENHTAB_6.FLDCOM AS FLDCOM6, GENHTAB_6.FLDDFORMAT AS FLDDFORMAT6, GENHTAB_6.FLDIFORMAT AS FLDIFORMAT6, GENHTAB_6.FLDTYPE AS FLDTYPE6, GENHTAB_6.SUBLINKF AS SUBLINKF6,  
 GENHTAB.FLDID7, GENHTAB.FLDTAG7, GENHTAB_7.FLDTAB AS FLDTAB7, GENHTAB_7.FLDCOM AS FLDCOM7, GENHTAB_7.FLDDFORMAT AS FLDDFORMAT7, GENHTAB_7.FLDIFORMAT AS FLDIFORMAT7, GENHTAB_7.FLDTYPE AS FLDTYPE7, GENHTAB_7.SUBLINKF AS SUBLINKF7,  
 GENHTAB.FLDID8, GENHTAB.FLDTAG8, GENHTAB_8.FLDTAB AS FLDTAB8, GENHTAB_8.FLDCOM AS FLDCOM8, GENHTAB_8.FLDDFORMAT AS FLDDFORMAT8, GENHTAB_8.FLDIFORMAT AS FLDIFORMAT8, GENHTAB_8.FLDTYPE AS FLDTYPE8, GENHTAB_8.SUBLINKF AS SUBLINKF8,  
 GENHTAB.FLDID9, GENHTAB.FLDTAG9, GENHTAB_9.FLDTAB AS FLDTAB9, GENHTAB_9.FLDCOM AS FLDCOM9, GENHTAB_9.FLDDFORMAT AS FLDDFORMAT9, GENHTAB_9.FLDIFORMAT AS FLDIFORMAT9, GENHTAB_9.FLDTYPE AS FLDTYPE9, GENHTAB_9.SUBLINKF AS SUBLINKF9,  
 GENHTAB.FLDID10, GENHTAB.FLDTAG10, GENHTAB_10.FLDTAB AS FLDTAB10, GENHTAB_10.FLDCOM AS FLDCOM10, GENHTAB_10.FLDDFORMAT AS FLDDFORMAT10, GENHTAB_10.FLDIFORMAT AS FLDIFORMAT10, GENHTAB_10.FLDTYPE AS FLDTYPE10, GENHTAB_10.SUBLINKF AS SUBLINKF10,  
 GENHTAB.FLDID11, GENHTAB.FLDTAG11, GENHTAB_11.FLDTAB AS FLDTAB11, GENHTAB_11.FLDCOM AS FLDCOM11, GENHTAB_11.FLDDFORMAT AS FLDDFORMAT11, GENHTAB_11.FLDIFORMAT AS FLDIFORMAT11, GENHTAB_11.FLDTYPE AS FLDTYPE11, GENHTAB_11.SUBLINKF AS SUBLINKF11,  
 GENHTAB.FLDID12, GENHTAB.FLDTAG12, GENHTAB_12.FLDTAB AS FLDTAB12, GENHTAB_12.FLDCOM AS FLDCOM12, GENHTAB_12.FLDDFORMAT AS FLDDFORMAT12, GENHTAB_12.FLDIFORMAT AS FLDIFORMAT12, GENHTAB_12.FLDTYPE AS FLDTYPE12, GENHTAB_12.SUBLINKF AS SUBLINKF12,  
 GENHTAB.FLDID13, GENHTAB.FLDTAG13, GENHTAB_13.FLDTAB AS FLDTAB13, GENHTAB_13.FLDCOM AS FLDCOM13, GENHTAB_13.FLDDFORMAT AS FLDDFORMAT13, GENHTAB_13.FLDIFORMAT AS FLDIFORMAT13, GENHTAB_13.FLDTYPE AS FLDTYPE13, GENHTAB_13.SUBLINKF AS SUBLINKF13,  
 GENHTAB.FLDID14, GENHTAB.FLDTAG14, GENHTAB_14.FLDTAB AS FLDTAB14, GENHTAB_14.FLDCOM AS FLDCOM14, GENHTAB_14.FLDDFORMAT AS FLDDFORMAT14, GENHTAB_14.FLDIFORMAT AS FLDIFORMAT14, GENHTAB_14.FLDTYPE AS FLDTYPE14, GENHTAB_14.SUBLINKF AS SUBLINKF14,  
 GENHTAB.FLDID15, GENHTAB.FLDTAG15, GENHTAB_15.FLDTAB AS FLDTAB15, GENHTAB_15.FLDCOM AS FLDCOM15, GENHTAB_15.FLDDFORMAT AS FLDDFORMAT15, GENHTAB_15.FLDIFORMAT AS FLDIFORMAT15, GENHTAB_15.FLDTYPE AS FLDTYPE15, GENHTAB_15.SUBLINKF AS SUBLINKF15  
