CREATE PROCEDURE [dbo].[QMasterAcceptance] (@P_ANO as integer) 
AS 
SELECT Acceptance.PolicyNo, Acceptance.CertificateNo, Acceptance.Branch, Acceptance.REGNO, Acceptance.ADATE, Acceptance.SDate, Acceptance.EDate, Acceptance.USERID, SysTab.Currency AS CCY, QPCalc.TSI, 
QPCalc.OurShare, QPCalc.Amount, QPCalc.Gross, QPCalc.Premium,  QPCalc.RYear, Acceptance.ATYPE, Acceptance.ASTATUS, Acceptance.LANO, Acceptance.ANO, Acceptance.CNO, 
Cover.ASource, Cover.PPeriod, Cover.CSTATUS, Cover.CoverNoteF, Cover.Voyage, Cover.OpenFlag, Acceptance.AdjustableF, Acceptance.RenewableF, Cover.ISType, Cover.PolicyType, Cover.TOC, Cover.MO, Acceptance.BANO,  Acceptance.RANO, Acceptance.RequestF, Acceptance.RequestName, 
ACCCOMPSHEETH.CID, acceptance.CANO , acceptance.ConjunctionF, pAcceptance.AType as pAType 
FROM Acceptance Left Join Acceptance pAcceptance on (pAcceptance.ANO=Acceptance.pANO) Left Join ACCCOMPSHEETH on (ACCCOMPSHEETH.ANO=Acceptance.OANO), FN_PCalc(@P_ANO) AS QPCalc, SysTab, Cover 
WHERE Acceptance.ANO=@P_ANO And Acceptance.CNO=Cover.CNO 
And QPCalc.ANO=Acceptance.ANO 
 
 

GO

 
/****** Object:  StoredProcedure [dbo].[QMissing_Risk]    Script Date: 3/2/2016 0:02:47 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE  procedure [dbo].[QMissing_Risk](@P_ANO integer) 
as 
Select Top 1 A1.ANO 
from RCover R1, Acceptance A1 
Where A1.ANO=@P_ANO and A1.ANO=R1.ANO 
and (R1.Category='A' or not ((R1.SDate=A1.SDate or  R1.SDate=A1.PDate) and R1.EDate=A1.EDate)) 
and R1.ANO not in 
( 
Select R2.ANO 
from RCover R2 
Where R2.Category='M' and R2.ANO=R1.ANO and not (R2.Code=R1.Code and R2.Sdate=R1.Sdate) 
and 
( 
(R2.Sdate<=R1.Edate and R2.Edate>=R1.Edate) or (R2.Sdate<=R1.Sdate and R2.Edate>=R1.Sdate) or 
(R1.Sdate<=R2.Sdate and R1.Edate>=R2.Sdate) or (R1.Sdate<=R2.Edate and R1.Edate>=R2.Edate) 
) 
) 
 

GO


 

