/****** Object:  StoredProcedure [dbo].[QPCALC_ACCASS]    Script Date: 3/2/2016 0:03:51 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[QPCALC_ACCASS] (@P_ANO integer) 
AS 
SELECT ICALC.CURRENCY, ICALC.CODE, ICALC.SDATE, ICALC.EDATE, (Case When A1.AType='A' Then 0 else ICover.Adjustable end) as AdjustableF, ICALC.SANO, A2.LANO, 
Cast(Max(cast(RCover.NoRefundF as Integer)) as Bit) as NoRefundF, 
Max(Case When ICover.Adjustable=1 Then TOI.AdjMethod else '' end) as AdjMethod, 
AVG(ICALC.PRORATA) AS PPRORATA, Max(Case When ISource.Share is null then 100 else ISource.Share end) AS SHARE, 
SUM(Case When PCALC.Description<>'' and PCALC.Description<>'Minimum Premium' then ICALC.GROSS*PCALC.GROSS/PCALC.OGROSS else ICALC.GROSS*RCALC.GROSS/RCALC.OGROSS end) AS GROSS, 
CAST(MAX(Case When Upper(PCALC.DESCRIPTION) in ('MINIMUM PREMIUM','POLICY MINIMUM PREMIUM') Then 1 else 0 end) as Bit) as MinimumPremiumF, 
SUM(ICALC.REINSTATEMENT) AS REINSTATEMENT, 
SUM(ICALC.DISCOUNT) AS DISCOUNT, 
MAX(R.TAmount*100/R.PCTSHARE) as TSI,      --100% Sum Insured for Reinsurance Rate 
MAX(PCALC.Rate) As Rate 
FROM ICover 
inner join ICALC on (ICALC.INO=ICOVER.INO and ICALC.ANO=ICOVER.ANO) 
inner join TOI on (TOI.TOI=ICOVER.TOI) 
inner join RCALC on (ICALC.ANO=RCALC.ANO AND ICALC.CURRENCY=RCALC.CURRENCY AND ICALC.CODE=RCALC.CODE AND ICALC.TOR=RCALC.TOR AND ICALC.SDATE=RCALC.SDATE AND ICALC.EDATE=RCALC.EDATE AND ICALC.SANO=RCALC.SANO) 
inner join PCALC on (PCALC.ANO=ICALC.ANO AND PCALC.CURRENCY=ICALC.CURRENCY) 
Left join RCover on (RCover.ANO=RCalc.ANO and RCover.Code=RCalc.Code and RCover.SDate=RCalc.SDate) 
inner join ACCEPTANCE A1 On (A1.ANO=ICALC.ANO) 
inner join ACCEPTANCE A2 on (A2.ANO=ICALC.SANO) 
Inner Join RArrHeader R on (R.ANO=ICalc.ANO) 
left join ISource on (ISource.CNO=A2.CNO) 
WHERE ICover.ANO=@P_ANO and ICALC.GROSS<>0 
GROUP BY ICALC.CURRENCY, ICALC.CODE, ICALC.SDATE, ICALC.EDATE, (Case When A1.AType='A' Then 0 else ICover.Adjustable end), ICalc.SANO, A2.LANO 
 
 

GO


 

/****** Object:  StoredProcedure [dbo].[QPOLICY_DEPOSIT]    Script Date: 3/2/2016 0:05:27 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[QPOLICY_DEPOSIT](@P_LANO integer) 
as 
Select 
sum(AccDeposit.Amount) as Total_Deposit 
from Acceptance MA1 
Inner Join Acceptance MA2 on (MA2.OANO=MA1.OANO) 
Inner join AccDeposit on (AccDeposit.ANO=MA2.ANO) 
Where MA1.ANO=@P_LANO and MA2.ANO<=@P_LANO 
 
 
 

GO


 

/****** Object:  StoredProcedure [dbo].[QPOLICY_DEPOSIT_USAGE]    Script Date: 3/2/2016 0:05:45 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[QPOLICY_DEPOSIT_USAGE](@P_ANO integer) 
as 
Select 
AccAss.Currency, 
sum(Case When AccAss.Code<>'J' Then AccAss.Amount else 0 end) as Total_Premium, 
sum(Case When AccAss.Code='J' Then -AccAss.Amount else 0 end) as Deposit_Usage 
from Acceptance A1 
Inner Join Acceptance MA1 on (MA1.ANO=A1.LANO) 
Inner Join Acceptance MA2 on (MA2.OANO=MA1.OANO) 
Inner Join Acceptance A2 on (A2.LANO=MA2.LANO and A2.ANO<>A2.LANO and A2.ANO<=@P_ANO) 
Inner Join AccAss on (AccAss.ANO=A2.ANO) 
Where A1.ANO=@P_ANO 
and ((AccAss.Type in ('DI','IC') and AccAss.Code in ('P','U','O','J')) or (AccAss.Type in ('IR','IT','IX') and AccAss.Code in ('P','O','J'))) 
Group by AccAss.Currency 
 
 
 

GO


 

/****** Object:  StoredProcedure [dbo].[QPolicy_Rate]    Script Date: 3/2/2016 0:05:52 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

Create Procedure [dbo].[QPolicy_Rate](@P_ANO as int) 
as 
Select ICALC.Code, ICALC.SDate, SUM(ICALC.TSI) as TSI, Max(ICALC.PrevMinRate) as PrevMinRate, Max(ICALC.PrevMaxRate) as PrevMaxRate, Max(ICALC.MinRate) as MinRate, Max(ICALC.MaxRate) as MaxRate 
from 
( 
Select ICALC.Code, ICALC.SDate, 
MAX((Case When ICover.Category='M' then ICALC.TSI else 0 end)*(CASE WHEN RCOVER.PCTLOSS=0 THEN 100 ELSE RCOVER.PCTLOSS END)/(CASE WHEN RCOVER.PCTLOSS=0 THEN 100 ELSE RCOVER.PCTLOSS END+RCOVER.PAddition)) as TSI, 
CAST(0 as FLOAT) as PREVMINRATE, 
CAST(0 as FLOAT) as PREVMAXRATE, 
ROUND(SUM(ICALC.GROSS*100/(100-RCover.Discount)/ICALC.TSI/(Case When RCOVER.LOADING=0 THEN 1 ELSE RCOVER.LOADING END)*Case When ICalc.PCTADJ<>0 Then cast(100 as Float)/ICALC.PCTADJ else 1 end*Case When ICALC.Prorata=1 then (Case When Day(ICALC.SDate)<>Day(ICALC.EDate) then cast(Cover.Prorata as Float)/datediff(day,ICALC.SDate, ICALC.EDate) else cast(12 as Float)/datediff(Month, ICALC.SDate, ICALC.EDate) end) else (Case When RCover.PCalc='P' and Cover.Voyage=0 then Case When day(ICalc.SDate)<>day(ICalc.EDate) or Cover.PPeriod=1 then cast(Cover.Prorata as Float)/datediff(day,ICalc.SDate, ICalc.EDate) else cast(12 as Float)/datediff(month,ICalc.SDate, ICalc.EDate) end else 1/ICALC.Prorata end) end)*100,13) as MINRATE, 
ROUND(SUM(ICALC.GROSS*100/(100-RCover.Discount)/ICALC.TSI/(Case When RCOVER.LOADING=0 THEN 1 ELSE RCOVER.LOADING END)*Case When ICalc.PCTADJ<>0 Then cast(100 as Float)/ICALC.PCTADJ else 1 end*Case When ICALC.Prorata=1 then (Case When Day(ICALC.SDate)<>Day(ICALC.EDate) then cast(Cover.Prorata as Float)/datediff(day,ICALC.SDate, ICALC.EDate) else cast(12 as Float)/datediff(Month, ICALC.SDate, ICALC.EDate) end) else (Case When RCover.PCalc='P' and Cover.Voyage=0 then Case When day(ICalc.SDate)<>day(ICalc.EDate) or Cover.PPeriod=1 then cast(Cover.Prorata as Float)/datediff(day,ICalc.SDate, ICalc.EDate) else cast(12 as Float)/datediff(month,ICalc.SDate, ICalc.EDate) end else 1/ICALC.Prorata end) end)*100,13) as MAXRATE 
from COVER, ACCEPTANCE, ICover, ICALC, RCover 
Where ACCEPTANCE.ANO=@P_ANO and COVER.CNO=ACCEPTANCE.CNO and COVER.ISType in ('I','C','L') and RCover.ANO=Acceptance.ANO 
and RCover.ANO=ICALC.ANO and RCover.Code=ICALC.Code and RCover.SDate=ICALC.SDate and RCover.EDate=ICALC.EDate and datediff(month, ICALC.SDate, ICALC.EDate)<>0 
and ICover.INO=ICalc.INO and ICALC.TSI<>0 
Group By ICalc.INO, ICALC.Code, ICALC.SDate 
 
Union All 
 
Select ICALC.Code, ICALC.SDate, 
0 as TSI, 
ROUND(SUM(ICALC.GROSS*100/(100-RCover.Discount)/ICALC.TSI/(Case When RCOVER.LOADING=0 THEN 1 ELSE RCOVER.LOADING END)*Case When ICalc.PCTADJ<>0 Then cast(100 as Float)/ICALC.PCTADJ else 1 end*Case When ICALC.Prorata=1 then (Case When Day(ICALC.SDate)<>Day(ICALC.EDate) then cast(Cover.Prorata as Float)/datediff(day,ICALC.SDate, ICALC.EDate) else cast(12 as Float)/datediff(Month, ICALC.SDate, ICALC.EDate) end) else (Case When RCover.PCalc='P' and Cover.Voyage=0 then Case When day(ICalc.SDate)<>day(ICalc.EDate) or Cover.PPeriod=1 then cast(Cover.Prorata as Float)/datediff(day,ICalc.SDate, ICalc.EDate) else cast(12 as Float)/datediff(month,ICalc.SDate, ICalc.EDate) end else 1/ICALC.Prorata end) end)*100,13) as PREVMINRATE, 
ROUND(SUM(ICALC.GROSS*100/(100-RCover.Discount)/ICALC.TSI/(Case When RCOVER.LOADING=0 THEN 1 ELSE RCOVER.LOADING END)*Case When ICalc.PCTADJ<>0 Then cast(100 as Float)/ICALC.PCTADJ else 1 end*Case When ICALC.Prorata=1 then (Case When Day(ICALC.SDate)<>Day(ICALC.EDate) then cast(Cover.Prorata as Float)/datediff(day,ICALC.SDate, ICALC.EDate) else cast(12 as Float)/datediff(Month, ICALC.SDate, ICALC.EDate) end) else (Case When RCover.PCalc='P' and Cover.Voyage=0 then Case When day(ICalc.SDate)<>day(ICalc.EDate) or Cover.PPeriod=1 then cast(Cover.Prorata as Float)/datediff(day,ICalc.SDate, ICalc.EDate) else cast(12 as Float)/datediff(month,ICalc.SDate, ICalc.EDate) end else 1/ICALC.Prorata end) end)*100,13) as PREVMAXRATE, 
CAST(0 as FLOAT) as MINRATE, 
CAST(0 as FLOAT) as MAXRATE 
from COVER, ACCEPTANCE, ACCEPTANCE PACCEPTANCE, ICover, ICALC, RCover 
Where ACCEPTANCE.ANO=@P_ANO and COVER.CNO=ACCEPTANCE.CNO and COVER.ISType in ('I','C','L') and PACCEPTANCE.ANO=ACCEPTANCE.PANO and RCOVER.ANO=PACCEPTANCE.ANO 
and RCover.ANO=ICALC.ANO and RCover.Code=ICALC.Code and RCover.SDate=ICALC.SDate and RCover.EDate=ICALC.EDate and datediff(month, ICALC.SDate, ICALC.EDate)<>0 
and ICover.INO=ICalc.INO and ICALC.TSI<>0 
Group By ICalc.INO, ICALC.Code, ICALC.SDate 
) ICALC 
Group By ICALC.Code, ICALC.SDate 
Having SUM(ICALC.TSI)<>0 
 
 

GO


 

