CREATE PROCEDURE [dbo].[QPREMIUMDUE] (@P_ANO AS INTEGER)
AS
SELECT
MIN(Voucher.NDueDate) As DueDate
FROM NVOUCHER VOUCHER, ADMLINK  WHERE VOUCHER.VOUCHER=ADMLINK.VOUCHER AND datediff(day,VOUCHER.NDUEDATE,getdate())>=0 AND ADMLINK.ADMNO
IN (SELECT ACCASS.ADMNO FROM ACCEPTANCE A1, ACCEPTANCE A2, ACCASS WHERE A1.ANO=@P_ANO AND A2.OANO=A1.OANO AND ACCASS.ANO=A2.ANO AND ACCASS.TYPE IN ('DI','IC','IR') AND ADMLINK.ADMNO=ACCASS.ADMNO)


GO


 
