CREATE  PROCEDURE [dbo].[QRCOVER] (@pANO as integer, @pCode as varchar(255),@pSDate as smalldatetime)
AS
SELECT *
FROM RCover
WHERE ANO=@pANO and Code=@pCode and SDate=@pSDate

 
