CREATE Procedure [dbo].[QREINSURANCE_TREATY] (@P_RYear integer, @P_TOC varchar(10), @P_RType varchar(10))
as
SELECT Reinsurance.RID, Reinsurance.RType, CASE ReClass.Limit WHEN 0 then Reinsurance.Limit else ReClass.Limit end as limit
FROM Reinsurance, ReClass
WHERE Reinsurance.RYear=@P_RYear and Reinsurance.RType=@P_RType And Reinsurance.RNO=ReClass.RNo And ReClass.TOC=@P_TOC




GO


 

/****** Object:  StoredProcedure [dbo].[QRemove_PHolder_LimitUsage]    Script Date: 3/2/2016 0:11:53 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

Create Procedure [dbo].[QRemove_PHolder_LimitUsage](@P_ANO as integer)
AS
Update PHolder Set TSILimitUsage=PHolder.TSILimitUsage-coalesce(TSI_Current.TSILimitUsage,0)
From 
	PHolder
	Inner join
    (
    Select Cover.PHolder, TOC.COB, sum(Case When Acceptance.AType<>'C' Then Pcalc.OurShare*PCalc.Rate else 0 end) as TSILimitUsage
    From PCalc, Acceptance, Cover, TOC
    Where Acceptance.ANO=@P_ANO and PCalc.ANO=Acceptance.ANO and Cover.CNO=Acceptance.CNO and TOC.TOC=Cover.TOC and Acceptance.AType in ('N','E','C')        
    Group by Cover.PHolder, TOC.COB
    ) TSI_Current on (PHolder.ID=TSI_Current.PHolder and PHolder.COB=TSI_Current.COB)
    

GO


 

/****** Object:  StoredProcedure [dbo].[QRenewalRight]    Script Date: 3/2/2016 0:11:59 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QRenewalRight](@P_ANO as int) 
AS 
Select Top 1 Renewal.RCode, Renewal.TOC, Acceptance.TOPRO as PrevTOPRO, RCover.Code as PrevCode, 
Coalesce(R2.TOPRO, R1.TOPRO) as TOPRO, 
Coalesce(R2.Code, R1.Code) as Code, 
Coalesce(R2.Discount, R1.Discount) as Discount, 
Coalesce(R2.RDiscount, R1.RDiscount) as RDiscount, 
Coalesce(R2.DLoading, R1.DLoading) as DLoading, 
Coalesce(R2.Deductible, R1.Deductible) as Deductible, 
Coalesce(R2.Loyalty, R1.Loyalty) as Loyalty, 
Coalesce(R2.Loyalty, R1.Rate) as Rate, 
Coalesce(R2.Unit, R1.Unit) as Unit, 
Interest.Currency, Interest.TSI, Interest.ATSI, 
Renewal.Loading 
from Acceptance 
Inner join Cover on (Cover.CNO=Acceptance.CNO) 
Inner Join Renewal on (Acceptance.ANO=Renewal.ANO and ((Renewal.RenewalF=1 and Renewal.Action=0) or Renewal.Action=2)) 
Inner Join RCover on (RCover.ANO=Acceptance.ANO and RCover.SDate=Acceptance.SDate and RCover.Category='M') 
Inner Join RenewalRight R1 on (R1.TOC=Renewal.TOC and R1.RCode=Renewal.RCode) 
Left Join RenewalRightCode R2 on (R1.TOC=R2.TOC and R1.RCode=R2.RCode and (R2.PrevTOPRO='<Any>' or R2.PrevTOPRO='' or R2.PrevTOPRO=Acceptance.TOPRO) and (R2.PrevCode='<Any>' or R2.PrevCode='' or R2.PrevCode=RCover.Code)) 
Left Join fn_sumInsured(@P_ANO) Interest on (Interest.ANO=@P_ANO) 
Where (Acceptance.ANO=@P_ANO and Acceptance.LANO<>Acceptance.ANO) or (Acceptance.LANO=@P_ANO and Acceptance.LANO<>-1 and Cover.OpenFlag=0) 
 
GO

/****** Object:  UserDefinedFunction [dbo].[FN_SumInsured]    Script Date: 3/2/2016 9:49:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create FUNCTION [dbo].[FN_SumInsured](@P_ANO as integer)  
RETURNS Table  
AS RETURN (  
Select ANO, Currency, sum(Case When Category='M' then SI else 0 end) as TSI, sum(Case When Category='A' then SI else 0 end) as ATSI 
from ICover Where ANO=@P_ANO 
Group By ANO, Currency
)  
GO

 

/****** Object:  StoredProcedure [dbo].[QRENEWALRULE]    Script Date: 3/2/2016 0:12:04 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QRENEWALRULE](@P_TOC as varchar(10),@P_POLICYTYPE as varchar(10),@P_SEGMENT as varchar(10),@P_ValueID1 as varchar(15), @P_ValueID2 as varchar(15), @P_ValueID3 as varchar(15), @P_ValueID4 as varchar(15), @P_ValueID5 as varchar(15), @P_Code 
as varchar(10), @P_LOSSRATIO as Float, @P_CLAIMFREQ as Float, @P_OWNFAULT as Float,@P_INSPERIOD as Float, @P_SUMINSURED as Float, @P_OUTGO as Float, @P_FacOpt as int, @P_PHOLDER as varchar(10)) 
AS 
SELECT TOP 1 coalesce(R2.RCode, R1.RCode) as RCode, coalesce(R2.RenewalF, R1.RenewalF) as RenewalF, R3.Notes, R1.OtherVar1, R1.OtherVar2, R1.OtherVar3, 
coalesce(R2.LOSSRATIOL, R1.LOSSRATIOL) as LOSSRATIOL, 
coalesce(R2.LOSSRATIOU, R1.LOSSRATIOU) as LOSSRATIOU, 
coalesce(R2.CLAIMFREQL, R1.CLAIMFREQL) as CLAIMFREQL, 
coalesce(R2.CLAIMFREQU, R1.CLAIMFREQU) as CLAIMFREQU, 
coalesce(R2.OWNFAULTL, R1.OWNFAULTL) as OWNFAULTL, 
coalesce(R2.OWNFAULTU, R1.OWNFAULTU) as OWNFAULTU, 
R1.INSPERIODL, R1.INSPERIODU, 
R1.SUMINSUREDL, R1.SUMINSUREDU, 
R1.OUTGOL, R1.OUTGOU 
FROM RENEWALRULE R1 
LEFT JOIN RENEWALRULEDET R2 ON (R2.RID=R1.RID AND (@P_LOSSRATIO BETWEEN R2.LOSSRATIOL AND R2.LOSSRATIOU) AND (@P_CLAIMFREQ BETWEEN R2.CLAIMFREQL AND R2.CLAIMFREQU) AND (@P_OWNFAULT BETWEEN R2.OWNFAULTL AND R2.OWNFAULTU)) 
LEFT JOIN RENEWALRIGHT R3 on (R3.TOC=@P_TOC and R3.RCODE=coalesce(R2.RCode, R1.RCode)) 
WHERE R1.TOC=@P_TOC 
AND (R1.POLICYTYPE=@P_POLICYTYPE or R1.POLICYTYPE in ('<All>','')) 
AND (R1.SEGMENT=@P_SEGMENT OR R1.SEGMENT='<All>') 
AND (right(space(15)+@P_ValueID1,15) Between (Case When ValueID1L in ('<All>','') then right(space(15)+@P_ValueID1,15) else right(space(15)+ValueID1L,15) end) and (Case When ValueID1U in ('') then (Case When ValueID1L in ('<All>','') then right(space(15)+@P_ValueID1,15) else right(space(15)+ValueID1L,15) end) When ValueID1U in ('<All>') then right(space(15)+@P_ValueID1,15) else right(space(15)+ValueID1U,15) end) or @P_ValueID1='') 
AND (right(space(15)+@P_ValueID2,15) Between (Case When ValueID2L in ('<All>','') then right(space(15)+@P_ValueID2,15) else right(space(15)+ValueID2L,15) end) and (Case When ValueID2U in ('') then (Case When ValueID2L in ('<All>','') then right(space(15)+@P_ValueID2,15) else right(space(15)+ValueID2L,15) end) When ValueID2U in ('<All>') then right(space(15)+@P_ValueID2,15) else right(space(15)+ValueID2U,15) end) or @P_ValueID2='') 
AND (right(space(15)+@P_ValueID3,15) Between (Case When ValueID3L in ('<All>','') then right(space(15)+@P_ValueID3,15) else right(space(15)+ValueID3L,15) end) and (Case When ValueID3U in ('') then (Case When ValueID3L in ('<All>','') then right(space(15)+@P_ValueID3,15) else right(space(15)+ValueID3L,15) end) When ValueID3U in ('<All>') then right(space(15)+@P_ValueID3,15) else right(space(15)+ValueID3U,15) end) or @P_ValueID3='') 
AND (right(space(15)+@P_ValueID4,15) Between (Case When ValueID4L in ('<All>','') then right(space(15)+@P_ValueID4,15) else right(space(15)+ValueID4L,15) end) and (Case When ValueID4U in ('') then (Case When ValueID4L in ('<All>','') then right(space(15)+@P_ValueID4,15) else right(space(15)+ValueID4L,15) end) When ValueID4U in ('<All>') then right(space(15)+@P_ValueID4,15) else right(space(15)+ValueID4U,15) end) or @P_ValueID4='') 
AND (right(space(15)+@P_ValueID5,15) Between (Case When ValueID5L in ('<All>','') then right(space(15)+@P_ValueID5,15) else right(space(15)+ValueID5L,15) end) and (Case When ValueID5U in ('') then (Case When ValueID5L in ('<All>','') then right(space(15)+@P_ValueID5,15) else right(space(15)+ValueID5L,15) end) When ValueID5U in ('<All>') then right(space(15)+@P_ValueID5,15) else right(space(15)+ValueID5U,15) end) or @P_ValueID5='') 
AND (R1.Code=@P_Code OR R1.Code in ('<All>','')) 
AND ((@P_LOSSRATIO BETWEEN R1.LOSSRATIOL AND R1.LOSSRATIOU) OR (R1.LOSSRATIOL=0 AND R1.LOSSRATIOU=0)) 
AND ((@P_CLAIMFREQ BETWEEN R1.CLAIMFREQL AND R1.CLAIMFREQU) OR (R1.CLAIMFREQL=0 AND R1.CLAIMFREQU=0)) 
AND ((@P_OWNFAULT BETWEEN R1.OWNFAULTL AND R1.OWNFAULTU) OR (R1.OWNFAULTL=0 AND R1.OWNFAULTU=0)) 
AND ((@P_INSPERIOD BETWEEN R1.INSPERIODL AND R1.INSPERIODU) OR (R1.INSPERIODL=0 AND R1.INSPERIODU=0)) 
AND ((@P_SUMINSURED BETWEEN R1.SUMINSUREDL AND R1.SUMINSUREDU) OR (R1.SUMINSUREDL=0 AND R1.SUMINSUREDU=0)) 
AND ((@P_OUTGO BETWEEN R1.OUTGOL AND R1.OUTGOU) OR (R1.OUTGOL=0 AND R1.OUTGOU=0)) 
AND (R1.FACOPT=0 or R1.FACOPT=@P_FACOPT) 
AND (R1.PHOLDER=@P_PHOLDER or R1.PHOLDER in ('<All>','')) 
ORDER BY 
R1.PRIORITYF DESC, 
coalesce(R2.RenewalF, R1.RenewalF), 
Case When R1.POLICYTYPE in ('<All>','') THEN 'zz' ELSE R1.POLICYTYPE END, 
Case When R1.SEGMENT in ('<All>','') THEN 'zzzzzzzzzz' ELSE R1.SEGMENT END, 
R1.FACOPT, 
right(space(15)+Case When R1.VALUEID1L in ('<All>','') THEN 'zzzzzzzzzzzzzzz' ELSE R1.VALUEID1L END,15), 
right(space(15)+Case When R1.VALUEID1U in ('<All>','') THEN 'zzzzzzzzzzzzzzz' ELSE R1.VALUEID1U END,15), 
right(space(15)+Case When R1.VALUEID2L in ('<All>','') THEN 'zzzzzzzzzzzzzzz' ELSE R1.VALUEID2L END,15), 
right(space(15)+Case When R1.VALUEID2U in ('<All>','') THEN 'zzzzzzzzzzzzzzz' ELSE R1.VALUEID2U END,15), 
right(space(15)+Case When R1.VALUEID3L in ('<All>','') THEN 'zzzzzzzzzzzzzzz' ELSE R1.VALUEID3L END,15), 
right(space(15)+Case When R1.VALUEID3U in ('<All>','') THEN 'zzzzzzzzzzzzzzz' ELSE R1.VALUEID3U END,15), 
right(space(15)+Case When R1.VALUEID4L in ('<All>','') THEN 'zzzzzzzzzzzzzzz' ELSE R1.VALUEID4L END,15), 
right(space(15)+Case When R1.VALUEID4U in ('<All>','') THEN 'zzzzzzzzzzzzzzz' ELSE R1.VALUEID4U END,15), 
right(space(15)+Case When R1.VALUEID5L in ('<All>','') THEN 'zzzzzzzzzzzzzzz' ELSE R1.VALUEID5L END,15), 
right(space(15)+Case When R1.VALUEID5U in ('<All>','') THEN 'zzzzzzzzzzzzzzz' ELSE R1.VALUEID5U END,15), 
R1.LOSSRATIOL, R1.LOSSRATIOU, 
R1.CLAIMFREQL, R1.CLAIMFREQU, 
R1.OWNFAULTL,R1.OWNFAULTU, 
R1.INSPERIODL, R1.INSPERIODU, 
R1.SUMINSUREDU, R1.SUMINSUREDL, 
R1.OUTGOL,R1.OUTGOU, 
Case When R1.PHOLDER in ('<All>','') THEN 'zzzzzzzzzz' ELSE R1.PHOLDER END 
 
 

GO


 

/****** Object:  StoredProcedure [dbo].[QRFACDET]    Script Date: 3/2/2016 0:12:09 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

Create Procedure [dbo].[QRFACDET] (@P_SANO integer, @P_ANO integer,@P_FID varchar(255), @P_CCY varchar(255), @P_SDate DateTime, @P_EDate DateTime, @P_Code varchar(10),@P_AdjustableF bit) 
as 
Select sum(Gross) as Gross 
from 
( 
select 
sum( 
Case When FPart.NetRate<>0 Then 
	   Case When FPart.Unit='F' Then FPart.NetRate/PCALC.RiskNum else FPart.NetRate/100/PCALC.RiskNum*(ICALC.TSI*ICALC.PCTADJ/100) end 
	   * 
	   Case When RArrDet.PCalc='P' or datediff(month,RArrDet.SDate, RArrDet.EDate)=0 or Cover.Voyage=1 Then 1 else 12/cast(datediff(month,RArrDet.SDate, RArrDet.EDate) as float) end 
	   *ICALC.GROSS/PCALC.GROSS 
else 
	   (ICALC.GROSS/PCALC.POGROSS*PCALC.PGROSS)/ICALC.PRORATA 
end 
) AS GROSS 
FROM ICALC, ICOVER, PCALC_ANNUM(@P_ANO) PCALC, FPART, RARRDET, ACCEPTANCE, COVER 
WHERE RARRDET.ANO=@P_SANO AND RARRDET.FID=@P_FID AND FPART.ANO=RARRDET.ANO AND FPART.FID=RARRDET.FID 
AND ICOVER.INO=ICALC.INO AND (ICOVER.ADJUSTABLE=@P_ADJUSTABLEF OR ACCEPTANCE.ATYPE='A') 
AND ICALC.ANO=@P_ANO AND ICALC.CURRENCY=@P_CCY 
AND PCALC.ANO=ICALC.ANO AND PCALC.CODE=ICALC.CODE AND PCALC.SDATE=ICALC.SDATE AND PCALC.EDATE=ICALC.EDATE AND PCALC.INO=ICALC.INO AND PCALC.CURRENCY=ICALC.CURRENCY 
AND ICALC.SDATE=@P_SDATE AND ICALC.EDATE=@P_EDATE AND ICALC.CODE=@P_CODE 
AND ACCEPTANCE.ANO=ICALC.ANO AND COVER.CNO=ACCEPTANCE.CNO 
AND PCALC.GROSS<>0 AND RARRDET.STATUS<>'O' 
AND RARRDET.FULLCOVERF=1 
Union All 
 
select 
Case When Max(FPart.NetRate)<>0 Then 
Max( 
Case When FPart.Unit='F' Then FPart.NetRate else FPart.NetRate/100*(ICALC.TSI*ICALC.PCTADJ/100) end 
* 
Case When RArrDet.PCalc='P' or datediff(month,RArrDet.SDate, RArrDet.EDate)=0 or Cover.Voyage=1 Then 1 else 12/cast(datediff(month,RArrDet.SDate, RArrDet.EDate) as float) 
end) 
else 
sum((ICALC.GROSS/PCALC.POGROSS*PCALC.PGROSS)/ICALC.PRORATA) 
end  AS GROSS 
FROM ICALC, ICOVER, PCALC_ANNUM(@P_ANO) PCALC, FPARTDET FPART, RATECOV, RARRDET, ACCEPTANCE, COVER 
WHERE RARRDET.ANO=@P_SANO AND RARRDET.FID=@P_FID AND FPART.ANO=RARRDET.ANO AND FPART.FID=RARRDET.FID AND RATECOV.CODE=FPART.CODE 
AND ICOVER.INO=ICALC.INO AND (ICOVER.ADJUSTABLE=@P_ADJUSTABLEF OR ACCEPTANCE.ATYPE='A') 
AND ICALC.ANO=@P_ANO AND ICALC.CURRENCY=@P_CCY 
AND PCALC.ANO=ICALC.ANO AND PCALC.CODE=ICALC.CODE AND PCALC.SDATE=ICALC.SDATE AND PCALC.EDATE=ICALC.EDATE AND PCALC.INO=ICALC.INO AND PCALC.CURRENCY=ICALC.CURRENCY 
AND ICALC.SDATE=@P_SDATE AND ICALC.EDATE=@P_EDATE AND ICALC.CODE=@P_CODE AND ICALC.TOR=RATECOV.TOR 
AND ACCEPTANCE.ANO=ICALC.ANO AND COVER.CNO=ACCEPTANCE.CNO 
AND PCALC.GROSS<>0 AND RARRDET.STATUS<>'O' 
AND RARRDET.FULLCOVERF=0 
Group by ICalc.Code 
) F 
 

GO


 

