SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[QScheme_Verify_3] 
@P_Coverage as varchar(255), 
@P_Code as varchar(10), 
@p_LMonth as float, 
@p_UMonth as float, 
@p_SchemeNo as varchar (10), 
@p_Description as varchar (255), 
@P_TSI as float=0 
as 
 
Declare @p_ClassNo int 
Declare @P_SIInceptionF Bit 
Select Top 1 @p_ClassNo=S2.ClassNo, @P_SIInceptionF=S1.SIInceptionF 
from scheme_Master S1, Scheme_Class S2 
Where S1.SchemeNo=@P_SchemeNo and S2.SchemeNo=S1.SchemeNo and @P_Description like S2.Description 
Order by S2.Priority Desc 
 
Select 
S1.Lower, 
S1.NoRefundF, 
S1.RateLoadingF, 
Coalesce(SI1.HoldF, S1.HoldF) as HoldF, 
Max(S1.Upper)as Upper, 
Max(S1.PCTLoss) as PCTLoss, 
Max(S1.PAddition) as PAddition, 
Max(coalesce(SI1.Discount, S1.Discount)) as Discount, 
Max(coalesce(SI1.RateLower, S1.RateLower)) as RateLower, 
Max(coalesce(SI1.Rate,S1.Rate)) as Rate 
From 
Scheme_Indemnity S1 
Left Join Scheme_Indemnity_TSI SI1 
On (SI1.ClassNo=S1.ClassNo and SI1.Coverage=S1.Coverage and SI1.Code=S1.Code and SI1.Lower=S1.Lower and SI1.Upper=S1.Upper 
and (@P_TSI*Case When @P_SIInceptionF=1 Then 1 Else S1.PCTLOSS/100 end>=SI1.MinTSI or SI1.MinTSI=0) and (@P_TSI*Case When @P_SIInceptionF=1 Then 1 Else S1.PCTLOSS/100 end<=SI1.MaxTSI or SI1.MaxTSI=0)) 
Where 
S1.ClassNo=@P_ClassNo 
and S1.Coverage=@P_Coverage 
and S1.Code=@P_Code 
and 
( 
(S1.Lower>=@p_LMonth and S1.Upper<=@p_UMonth) 
or 
(S1.Lower<=@p_LMonth and S1.Upper>=@p_UMonth) 
or 
(S1.Lower<=@p_LMonth and S1.Upper>=@p_LMonth) 
or 
(S1.Lower<=@p_UMonth and S1.Upper>=@p_UMonth) 
) 
and NOT EXISTS (Select S3.ClassNo from Scheme_Indemnity S3 Where S3.ClassNo=S1.ClassNo and S3.Coverage=S1.Coverage and S3.Code=S1.Code and S1.Lower=S3.Lower and S1.Upper>S3.Upper and S3.Lower<=@P_LMonth and S3.Upper>=@P_UMonth) 
and NOT EXISTS (Select S3.ClassNo from Scheme_Indemnity S3 Where S3.ClassNo=S1.ClassNo and S3.Coverage=S1.Coverage and S3.Code=S1.Code and S1.Lower=S3.Lower and S1.Upper<S3.Upper and S3.Lower>=@P_LMonth and S3.Upper<=@P_UMonth) 
Group By S1.Lower, S1.NoRefundF, S1.RateLoadingF, Coalesce(SI1.HoldF, S1.HoldF) 
Order By S1.Lower, S1.NoRefundF, S1.RateLoadingF, Coalesce(SI1.HoldF, S1.HoldF) 
 
 

GO


 
/****** Object:  StoredProcedure [dbo].[QScheme_Verify_4]    Script Date: 3/2/2016 0:13:23 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[QScheme_Verify_4](@p_SchemeNo as varchar (10), @p_Description as varchar (255)) 
as 
 
Declare @p_ClassNo int 
Declare @p_Priority int 
Select Top 1 @p_ClassNo=S.ClassNo, @p_Priority=s.Priority 
from Scheme_Class S Where S.SchemeNo=@P_SchemeNo and @P_Description like S.Description 
Order by Priority Desc 
 
 
select distinct 
TOI.TOI, 
TOI.Description, 
TOI.Adjustable, 
S1.Category, 
S1.SI 
From 
scheme_interest as S1, 
scheme_coverage as S2, 
scheme_class as SC1, 
Scheme_Class as SC2, 
PClass, 
RateCov, 
TOI 
Where 
TOI.TOI = s1.TOI 
and RateCov.Code=S2.Code 
and PClass.TOI=TOI.TOI 
and PClass.TOR=RateCov.TOR 
and SC1.ClassNo=S1.ClassNo 
and SC2.ClassNo=S2.ClassNo 
and SC1.SchemeNo=SC2.SchemeNo 
and SC2.SchemeNo=@p_SchemeNO 
and @p_Description Like SC1.Description 
and @p_Description Like SC2.Description 
and SC2.Priority <= @p_Priority 
 
 
 

GO


 

/****** Object:  StoredProcedure [dbo].[QScheme_Verify_5]    Script Date: 3/2/2016 0:13:29 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE Procedure [dbo].[QScheme_Verify_5]  
@p_ANO as integer,  
@p_TSI as float,  
@P_Coverage as varchar(255),  
@p_SchemeNo as varchar (10),  
@p_Description as varchar (255)  
as  
Select S1.DCode, S1.PCTTSI, S1.PCTCL, S1.FIXEDMIN, S1.FIXEDMAX, S1.Currency, S1.IUNIT, S1.Remarks, S1.TOR, S1.STRTSI  
from Scheme_Deductible S1, Scheme_Class S2, Scheme_Coverage S3, RateCov  
Where  
S1.Coverage=@P_Coverage  
and S1.Lower<=@p_TSI  
and S1.Upper>=@p_TSI  
and S2.ClassNo=S1.ClassNo  
and S2.SchemeNo=@p_SchemeNO  
and @p_Description Like S2.Description  
and S3.Coverage=@P_Coverage  
and S3.ClassNo=S2.ClassNo  
and RateCov.Code=S3.Code  
and S1.TOR=RateCov.TOR  
and S2.Priority in (Select Max(S3.Priority) from Scheme_Class S3 Where S3.SchemeNo=@P_SchemeNo and @P_Description like S3.Description)  
      
    

GO


 
/****** Object:  StoredProcedure [dbo].[QScheme_Verify_6]    Script Date: 3/2/2016 0:13:36 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[QScheme_Verify_6] 
@p_Coverage as varchar (255), 
@p_Interest as varchar (20), 
@p_TSI as float, 
@P_NOfYears as float, 
@p_SchemeNo as varchar (10), 
@p_Description as varchar (255) 
as 
Select 
S1.SI, S1.IncludeF, S1.Rate, S1.Code, S1.Unit, S1.Category, S1.Portion, S1.TOI, S1.NOTDECRF, S1.RateBasedID, 
TOI.Description as TOIDesc, 
TOI.Adjustable, 
RateTab.Description as RateDesc 
from 
RateTab, 
TOI, 
Scheme_Additional S1, 
Scheme_Class S2 
Where 
RateTab.Code=S1.Code 
and TOI.TOI=S1.TOI 
and (S1.Coverage='' or S1.Coverage=@P_Coverage) 
and S1.Interest=@p_Interest 
and (S1.Lower<=Case When @p_TSI=0 then (Case When S1.IncludeF=1 Then S1.SI else 0 end)else @P_TSI end or S1.Lower=0) 
and (S1.Upper>=Case When @p_TSI=0 then (Case When S1.IncludeF=1 Then S1.SI else 0 end)else @P_TSI end or S1.Upper=0) 
and (S1.NOfYearsL<=@p_NOfYears or S1.NOfYearsL=0) 
and (S1.NOfYearsU>=@p_NOfYears or S1.NOfYearsU=0) 
and S2.ClassNo=S1.ClassNo 
and S2.SchemeNo=@p_SchemeNO 
and @p_Description Like S2.Description 
and S2.Priority=coalesce((Select Top 1 S3.Priority from Scheme_Class S3 Where S3.SchemeNo=@P_SchemeNo and @P_Description like S3.Description Order By S3.Priority Desc),0) 
 
 

GO


 
