From RateTab, RateCov, Rclass
Where RateTab.Code Like @P_Code and RateTab.Code=RateCov.Code and Rclass.TOR=RateCov.TOR and Rclass.TOC=@P_TOC
Group By [RateTab].[Code], [RateTab].[Description], [RateTab].[Unit]
 
