 LEFT OUTER JOIN GENHTAB as GENHTAB_7 ON TOI.FLDID7 = GENHTAB_7.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_8 ON TOI.FLDID8 = GENHTAB_8.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_9 ON TOI.FLDID9 = GENHTAB_9.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_10 ON TOI.FLDID10 = GENHTAB_10.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_11 ON TOI.FLDID11 = GENHTAB_11.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_12 ON TOI.FLDID12 = GENHTAB_12.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_13 ON TOI.FLDID13 = GENHTAB_13.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_14 ON TOI.FLDID14 = GENHTAB_14.FLDID      
