CREATE PROCEDURE [dbo].[TREATY_ADJUSTMENT_LIMIT] (@P_REGID as varchar(10), @P_FLDID as varchar(255), @P_VALUEID as varchar(255))  
AS  
Select MIN(CASE WHEN LIMIT=0 THEN 1 ELSE LIMIT END) AS LIMIT, MAX(YEAR(RARRHEADER.RDATE)) as RYEAR
From RARRHEADER, acceptance  
WHERE RARRHEADER.STATUS='A' AND RARRHEADER.ANO=ACCEPTANCE.ANO AND ACCEPTANCE.ASTATUS='W' and ACCEPTANCE.REGID=@P_REGID AND ACCEPTANCE.FLDID=@P_FLDID AND ACCEPTANCE.VALUEID=@P_VALUEID  
    



