CREATE PROCEDURE [dbo].[Update_Installment] (@P_Branch as varchar(10),@P_Date as smalldatetime)
As
UPDATE VOUCHER SET
NDUEDATE=
      CASE
      WHEN (AMOUNTDUE_1)-PAYMENT_CC>0 THEN DUEDATE_1
      WHEN (AMOUNTDUE_1+AMOUNTDUE_2)-PAYMENT_CC>0 THEN DUEDATE_2
      WHEN (AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3)-PAYMENT_CC>0 THEN DUEDATE_3
      WHEN (AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4)-PAYMENT_CC>0 THEN DUEDATE_4
      WHEN (AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5)-PAYMENT_CC>0 THEN DUEDATE_5
      WHEN (AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6)-PAYMENT_CC>0 THEN DUEDATE_6
      WHEN (AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7)-PAYMENT_CC>0 THEN DUEDATE_7
      WHEN (AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8)-PAYMENT_CC>0 THEN DUEDATE_8
      WHEN (AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8+AMOUNTDUE_9)-PAYMENT_CC>0 THEN DUEDATE_9
      WHEN (AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8+AMOUNTDUE_9+AMOUNTDUE_10)-PAYMENT_CC>0 THEN DUEDATE_10
      WHEN (AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8+AMOUNTDUE_9+AMOUNTDUE_10+AMOUNTDUE_11)-PAYMENT_CC>0 THEN DUEDATE_11
      WHEN (AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8+AMOUNTDUE_9+AMOUNTDUE_10+AMOUNTDUE_11+AMOUNTDUE_12)-PAYMENT_CC>0 THEN DUEDATE_12
      END,
AMOUNTDUE=
      CASE
      WHEN DUEDATE_1>=@P_DATE THEN AMOUNTDUE_1
      WHEN DUEDATE_2>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2
      WHEN DUEDATE_3>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3
      WHEN DUEDATE_4>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4
      WHEN DUEDATE_5>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5
      WHEN DUEDATE_6>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6
      WHEN DUEDATE_7>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7
      WHEN DUEDATE_8>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8
      WHEN DUEDATE_9>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8+AMOUNTDUE_9
      WHEN DUEDATE_10>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8+AMOUNTDUE_9+AMOUNTDUE_10
      WHEN DUEDATE_11>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8+AMOUNTDUE_9+AMOUNTDUE_10+AMOUNTDUE_11
      WHEN DUEDATE_12>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8+AMOUNTDUE_9+AMOUNTDUE_10+AMOUNTDUE_11+AMOUNTDUE_12
      END,
CINSTALLMENT=
      CASE
      WHEN DUEDATE_1>=@P_DATE THEN 1
      WHEN DUEDATE_2>=@P_DATE THEN 2
      WHEN DUEDATE_3>=@P_DATE THEN 3
      WHEN DUEDATE_4>=@P_DATE THEN 4
      WHEN DUEDATE_5>=@P_DATE THEN 5
      WHEN DUEDATE_6>=@P_DATE THEN 6
      WHEN DUEDATE_7>=@P_DATE THEN 7
      WHEN DUEDATE_8>=@P_DATE THEN 8
      WHEN DUEDATE_9>=@P_DATE THEN 9
      WHEN DUEDATE_10>=@P_DATE THEN 10
      WHEN DUEDATE_11>=@P_DATE THEN 11
      WHEN DUEDATE_12>=@P_DATE THEN 12
      END,
AMOUNTUNDUE=NOMINAL_CC-DIFF_CC-
(      CASE
      WHEN DUEDATE_1>=@P_DATE THEN AMOUNTDUE_1
      WHEN DUEDATE_2>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2
      WHEN DUEDATE_3>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3
      WHEN DUEDATE_4>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4
      WHEN DUEDATE_5>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5
      WHEN DUEDATE_6>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6
      WHEN DUEDATE_7>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7
      WHEN DUEDATE_8>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8
      WHEN DUEDATE_9>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8+AMOUNTDUE_9
      WHEN DUEDATE_10>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8+AMOUNTDUE_9+AMOUNTDUE_10
      WHEN DUEDATE_11>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8+AMOUNTDUE_9+AMOUNTDUE_10+AMOUNTDUE_11
      WHEN DUEDATE_12>=@P_DATE THEN AMOUNTDUE_1+AMOUNTDUE_2+AMOUNTDUE_3+AMOUNTDUE_4+AMOUNTDUE_5+AMOUNTDUE_6+AMOUNTDUE_7+AMOUNTDUE_8+AMOUNTDUE_9+AMOUNTDUE_10+AMOUNTDUE_11+AMOUNTDUE_12
      End
)
FROM NVOUCHER VOUCHER
WHERE VOUCHER.BRANCH=@P_BRANCH and VOUCHER.INSTALLMENT<>0 and VOUCHER.DATE<=@P_DATE and VOUCHER.MDUEDATE>=@P_DATE


GO



 
