SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[QCA_FX_Position] (@P_Branch as varchar(10), @P_ComAcc as varchar(20), @P_Date as smalldatetime) AS
declare @P_Month as smallint
declare @P_Year as smallint
select @P_Month=month(@P_Date)
select @P_Year=Year(@P_Date)
select C.ComAcc, Max(C.Starting) as Starting, sum(case When V.DebtorF=1 then V.Nominal_CC-V.Diff_CC else -(V.Nominal_CC-V.Diff_CC) end) as Mutation from QCA_FX(@P_Month, @P_Year,@P_Branch,@P_ComAcc)  C 
Left Join Voucher V on (V.Branch=C.Branch and V.ComAcc=C.ComAcc and V.Date<=@P_Date) 
Group By C.ComAcc


GO


