/****** Object:  UserDefinedFunction [dbo].[Coinsurance_Commission]    Script Date: 3/2/2016 9:49:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
Create Function [dbo].[Coinsurance_Commission](@P_ANO as int,@P_Code as varchar(10))
RETURNS Float
AS
BEGIN
 Declare @Commission Float
 Declare @CommissionDet Float
        
 Select @Commission=sum(Coinsurance.Share/100*(Coinsurance.Comm))
 From Coinsurance, acceptance
 Where Coinsurance.CNO=Acceptance.CNO and Acceptance.ANO=@P_ANO
 and Coinsurance.CNO not in (Select CNO from CoinsuranceDet Where CoinsuranceDet.ID=Coinsurance.ID and CoinsuranceDet.CNO=Coinsurance.CNO and CoinsuranceDet.Code=@P_Code)
        
 if @Commission is null
   Select @Commission=0

 Select @CommissionDet=sum(Coinsurance.Share/100*(CoinsuranceDet.Comm))
 From CoinsuranceDet, Coinsurance, acceptance
 Where Coinsurance.CNO=Acceptance.CNO and Acceptance.ANO=@P_ANO and CoinsuranceDet.CNO=Coinsurance.CNO and CoinsuranceDet.ID=Coinsurance.ID and CoinsuranceDet.Code=@P_Code

 if @CommissionDet is null
   Select @CommissionDet=0
        
 return(@Commission+@CommissionDet)
End
  
  
GO


/****** Object:  UserDefinedFunction [dbo].[Payor_Discount]    Script Date: 3/2/2016 9:49:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Function [dbo].[Payor_Discount](@P_ANO as int,@P_Code as varchar(10),@P_Period as int=0)        
RETURNS @DISCOUNT TABLE (GDISCOUNT Float, PDISCOUNT Float, DISCOUNT Float)
AS        
BEGIN        
 Declare @PDiscount Float        
 Declare @GDiscount Float        
 Declare @TDiscount Float        
 Declare @RegNo varchar(20)  
 Declare @AStatus varchar(1)  
              
 -- Payor Discount from Alternate Discount        
 Select @PDiscount=APayor.Discount from APayor Where ANO=@P_ANO        
 Select @RegNo=RegNo, @AStatus=AStatus from Acceptance Where ANO=@P_ANO  
   
 if @PDiscount is null        
 BEGIN         
 if @RegNo='' or @AStatus in ('W','T')  
 Begin     
  Select @PDiscount=Payor.Discount, @GDiscount=Payor.GDiscount, @TDiscount=PayorDet.Discount     
  from Acceptance Left Join Acceptance mAcceptance on (mAcceptance.ANO=mAcceptance.LANO and mAcceptance.ANO=Acceptance.LANO),    
  Payor Left Join PayorDet on (PayorDet.ANO=Payor.ANO and PayorDet.Code=@P_Code and (PayorDet.Period=0 or PayorDet.Period=@P_Period))    
  Where Acceptance.ANO=@P_ANO and Acceptance.AStatus in ('W','T')and (Acceptance.ANO=Payor.ANO or mAcceptance.ANO=Payor.ANO)         
    end  
    else  
    Begin  
  Select @PDiscount=Payor.Discount, @GDiscount=Payor.GDiscount, @TDiscount=PayorDet.Discount     
  from Acceptance Left Join Acceptance mAcceptance on (mAcceptance.ANO=mAcceptance.LANO and ((mAcceptance.RegNo<>'' and mAcceptance.RegNo=Acceptance.RegNo))),    
  Payor Left Join PayorDet on (PayorDet.ANO=Payor.ANO and PayorDet.Code=@P_Code and (PayorDet.Period=0 or PayorDet.Period=@P_Period))    
  Where Acceptance.ANO=@P_ANO and Acceptance.RegNo<>'' and Acceptance.AStatus not in ('W','T') and (Acceptance.ANO=Payor.ANO or mAcceptance.ANO=Payor.ANO)             
    end  
    if @TDiscount is not null        
        Select @PDiscount=@TDiscount        
 End        
 Else        
 BEGIN        
    Select @TDiscount=PayorDet.Discount from APayorDet PayorDet Where PayorDet.ANO=@P_ANO and PayorDet.Code=@P_Code and (PayorDet.Period=0 or PayorDet.Period=@P_Period)        
    if @TDiscount is not null        
        Select @PDiscount=@TDiscount        
    Select @GDiscount=0        
 End        
                     
 insert into @Discount(GDiscount, PDiscount, Discount) Select @GDiscount, @PDiscount, @GDiscount+(1 - @GDiscount / 100)*@PDiscount        
 Return
End        
  



GO
/****** Object:  UserDefinedFunction [dbo].[Payor_Group_Discount]    Script Date: 3/2/2016 9:49:20 ******/
