GO

CREATE Function [dbo].[Premium_HandlingFee](@P_ANO as int,@P_Code as varchar(10),@P_Period Int)          
RETURNS Float          
AS          
BEGIN          
 Declare @FEE Float 
 Declare @DetailF bit          
                                            
 Select Top 1 @DetailF=1 from ISourceDet, Acceptance Where ISourceDet.CNO=Acceptance.CNO and Acceptance.ANO=@P_ANO                  
 if @DetailF is null   
 Select @DetailF=0     
   
 if @DetailF=1  
 Begin   
	Select @FEE=ISourceDet.FEE+ISourceDet.HF from ISourceDet, Acceptance Where ISourceDet.CNO=Acceptance.CNO and Acceptance.ANO=@P_ANO and ISourceDet.Code=@P_Code
 end   
 else 
 Begin   
	Select @FEE=ISource.FEE+ISource.HF+ISource.OC from ISource, Acceptance Where ISource.CNO=Acceptance.CNO and Acceptance.ANO=@P_ANO 
 end  
                  
 if @FEE is null          
   Select @FEE=0          
                  
 return(@FEE)          
End          
  
GO
