/****** Object:  UserDefinedFunction [dbo].[Premium_Overriding]    Script Date: 3/2/2016 9:49:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE Function [dbo].[Premium_Overriding](@P_ANO as int,@P_Code as varchar(10),@P_Period Int)
RETURNS Float
AS
BEGIN
 Declare @PDiscount Float
 Declare @RDiscount Float
 Declare @ADiscount Float
 Declare @MShare Float
 Declare @Commission Float
          
 select @ADiscount=Discount from Acceptance Where ANO=@P_ANO
 Select @PDiscount=dbo.Payor_Discount(@P_ANO,@P_Code,@P_Period)
 Select @RDiscount=dbo.Rate_Discount(@P_ANO)
 Select @MShare=dbo.Member_Share(@P_ANO)
          
 Select @Commission=sum(Commission)
 From
 (
 Select (case When AccBS.NetF=1 Then
         Case When AccBS.GrossF=1 Then 100/(100-@RDiscount)*(1-@PDiscount/100)*AccBS.Fee else (1-@PDiscount/100)*AccBS.Fee end
        Else
         Case When AccBS.GrossF=1 Then 100/(100-@RDiscount)*AccBS.Fee else AccBS.Fee end
        end)*(Case When AccBS.MemberF=1 Then (1-@MShare/100) else 1 end)-(Case When @ADiscount=0 then AccBS.Discount else @ADiscount end) as Commission
 From AccBS, acceptance, MParam, Profile
 Where AccBS.BSType='O' and MParam.Type='B'+AccBS.BSType and Profile.ID=AccBS.ID
 and (Acceptance.ANO=AccBS.ANO or Acceptance.LANO=AccBS.ANO) and Acceptance.ANO=@P_ANO
 and AccBS.ANO not in (Select ANO from AccBSDet Where (AccBSDet.Period=0 or AccBSDet.Period=@P_Period) and AccBSDet.ID=AccBS.ID and AccBSDet.BSType=AccBS.BSType and AccBSDet.ANO=AccBS.ANO and AccBSDet.Code=@P_Code)
 and Acceptance.ANO not in (Select ANO from AAccBS Where AAccBS.ANO=Acceptance.ANO)
          
 Union All
          
 Select (case When AccBS.NetF=1 Then
         Case When AccBS.GrossF=1 Then 100/(100-@RDiscount)*(1-@PDiscount/100)*AccBSDet.Fee else (1-@PDiscount/100)*AccBSDet.Fee end
        Else
         Case When AccBS.GrossF=1 Then 100/(100-@RDiscount)*AccBSDet.Fee else AccBSDet.Fee end
        end)*(Case When AccBS.MemberF=1 Then (1-@MShare/100) else 1 end)-(Case When @ADiscount=0 then AccBSDet.Discount else @ADiscount end) as Commission
 From AccBSDet, AccBS, acceptance, MParam, Profile
 Where AccBS.BSType='O' and MParam.Type='B'+AccBS.BSType and Profile.ID=AccBS.ID
 and (Acceptance.ANO=AccBSDet.ANO or Acceptance.LANO=AccBSDet.ANO) and Acceptance.ANO=@P_ANO and (AccBSDet.Period=0 or AccBSDet.Period=@P_Period) and AccBSDet.Code=@P_Code and AccBS.ANO=AccBSDet.ANO and AccBS.ID=AccBSDet.ID and AccBS.BSType=AccBSDet.BSType
 and Acceptance.ANO not in (Select ANO from AAccBS Where AAccBS.ANO=Acceptance.ANO)
          
 Union All
          
 Select (case When AAccBS.NetF=1 Then
         Case When AAccBS.GrossF=1 Then 100/(100-@RDiscount)*(1-@PDiscount/100)*AAccBS.Fee else (1-@PDiscount/100)*AAccBS.Fee end
        Else
         Case When AAccBS.GrossF=1 Then 100/(100-@RDiscount)*AAccBS.Fee else AAccBS.Fee end
        end)*(Case When AAccBS.MemberF=1 Then (1-@MShare/100) else 1 end)-(Case When @ADiscount=0 then AAccBS.Discount else @ADiscount end) as Commission
 From AAccBS, acceptance, MParam, Profile
 Where AAccBS.BSType='O' and MParam.Type='B'+AAccBS.BSType and Profile.ID=AAccBS.ID
 and Acceptance.ANO=AAccBS.ANO and Acceptance.ANO=@P_ANO
 and AAccBS.ANO not in (Select ANO from AAccBSDet Where (AAccBSDet.Period=0 or AAccBSDet.Period=@P_Period) and AAccBSDet.ID=AAccBS.ID and AAccBSDet.BSType=AAccBS.BSType and AAccBSDet.ANO=AAccBS.ANO and AAccBSDet.Code=@P_Code)
          
 Union All
           
 Select (case When AAccBS.NetF=1 Then
         Case When AAccBS.GrossF=1 Then 100/(100-@RDiscount)*(1-@PDiscount/100)*AAccBSDet.Fee else (1-@PDiscount/100)*AAccBSDet.Fee end
        Else
         Case When AAccBS.GrossF=1 Then 100/(100-@RDiscount)*AAccBSDet.Fee else AAccBSDet.Fee end
        end)*(Case When AAccBS.MemberF=1 Then (1-@MShare/100) else 1 end)-(Case When @ADiscount=0 then AAccBSDet.Discount else @ADiscount end) as Commission
 From AAccBSDet, AAccBS, acceptance, MParam, Profile
 Where AAccBS.BSType='O' and MParam.Type='B'+AAccBS.BSType and Profile.ID=AAccBS.ID
 and Acceptance.ANO=AAccBSDet.ANO and Acceptance.ANO=@P_ANO and (AAccBSDet.Period=0 or AAccBSDet.Period=@P_Period) and AAccBSDet.Code=@P_Code and AAccBS.ANO=AAccBSDet.ANO and AAccBS.ID=AAccBSDet.ID and AAccBS.BSType=AAccBSDet.BSType
           
 ) T
          
  if @Commission is null
   Select @Commission=0
          
 return(@Commission)
End
        

GO
