CREATE Function [dbo].[fn_Age](@BirthDate smalldatetime,@ComparisonDate as smalldatetime,@AgeMethod as int)      
RETURNS INT AS      
BEGIN    
 declare @Age as int     
 declare @NumMonths as int 
 set @Age=0      
 if @AgeMethod=0 
 Begin
  set @Age=datediff(year,@BirthDate,@ComparisonDate)
 End
 else 
 if @AgeMethod=1 --Month Rounding
 Begin
  set @Age=round(cast(datediff(month,@BirthDate,@ComparisonDate) as Float)/cast(12 as Float),0)
 End
 else 
 if @AgeMethod=2 --Day Rounding
 Begin
     set @ComparisonDate=dateadd(day,-1,@ComparisonDate)
  set @NumMonths=datediff(month,@BirthDate,@ComparisonDate)
  if datediff(day,@ComparisonDate,dateadd(month,@NumMonths, @BirthDate))>0
   set @NumMonths=@NumMonths-1
 
  Declare @TDate1 as smalldatetime
  Declare @TDate2 as smalldatetime
  set @TDate1=dateadd(month,@NumMonths, @BirthDate)
  set @TDate2=dateadd(month,@NumMonths+1, @BirthDate)
  if datediff(day,@TDate1,@ComparisonDate) < datediff(day,@ComparisonDate, @TDate2)
   set @NumMonths=@NumMonths   
  else
  Begin
   set @NumMonths=@NumMonths-1
   if  (@NumMonths % 12)=6
    set @NumMonths=@NumMonths-1 
  End
  set @Age=round(cast(@NumMonths as Float)/cast(12 as Float),0)
 End
 else
 Begin
  set @Age=datediff(month,@BirthDate,@ComparisonDate)/12
 End
 return @Age
END


GO
Create FUNCTION [dbo].[fn_SL_Payment_Nominal] (@Nominal as float, @PSL_Cat as varchar(1), @PDebtorF as bit, @DebtorF as bit)  
RETURNS Float  
AS   
BEGIN  
if @DebtorF=1   
Begin  
 if @PSL_Cat in ('A','B','P')   
 begin  
  if @PDebtorF=@DebtorF   
  Begin  
   return(@Nominal)  
  end  
  else  
  begin  
   return(-@Nominal)  
  end  
 end  
 else  
 begin  
  if @PDebtorF=@DebtorF  
  Begin  
   return(-@Nominal)  
  end  
  else  
  begin  
   return(@Nominal)  
  End  
 end  
end  
else  
begin  
 if @PSL_Cat in ('A','B','P')   
 begin  
  if @PDebtorF=@DebtorF   
  Begin  
   return(-@Nominal)  
  end  
  else  
  begin  
   return(@Nominal)  
  end  
 end  
 else  
 begin  
  if @PDebtorF=@DebtorF  
  Begin  
   return(@Nominal)  
  end  
  else  
  begin  
   return(-@Nominal)  
  End  
 end  
end  
return(@Nominal)  
END  
 

GO
