Create Function [dbo].[Coinsurance_HandlingFee](@P_ANO as int)
RETURNS Float
AS
BEGIN
 Declare @HandlingFee Float
        
 Select @HandlingFee=sum(Coinsurance.Share/100*(Coinsurance.HF))
 From Coinsurance, acceptance
 Where Coinsurance.CNO=Acceptance.CNO and Acceptance.ANO=@P_ANO
        
 if @HandlingFee is null
   Select @HandlingFee=0
        
 return(@HandlingFee)
End
 
GO

