CREATE  FUNCTION [dbo].[DateSerial] (@Year as int,@Month as int,@Day as int)
RETURNS SMALLDATETIME 
AS 
BEGIN
	DECLARE @DateBuf as varchar(10),@DateResult as smalldatetime
	
	set @DateBuf=cast(@year as varchar(4))
	set @DateBuf=@DateBuf+'-'+cast(@month as varchar(2))
	set @DateBuf=@DateBuf+'-'+cast(@day as varchar(2))
	set @DateResult=cast(@DateBuf as smalldatetime)
	return(@DateResult)
END


GO  
 


/****** Object:  UserDefinedFunction [dbo].[FacPremium]    Script Date: 3/2/2016 9:49:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[FacPremium]  
(  
 @P_SANO integer,  
 @P_ANO integer,  
 @P_FID varchar(255),  
 @P_CCY varchar(255),  
 @P_SDate smalldatetime,  
 @P_EDate smalldatetime,  
 @P_Code varchar(10),  
 @P_INO int,  
 @P_TOR varchar(10),  
 @P_AdjustableF bit,  
 @P_FullCoverF bit,  
 @P_NetRate float,  
 @P_QTY Float,  
 @P_FlPct Float,  
 @P_Share Float,  
 @P_RShare Float,  
 @P_Ujroh Float = 0  
)   
RETURNS Float  
AS  
  
BEGIN  
    DECLARE @FacPremium AS Float  
    DECLARE @Premium AS Float  
    DECLARE @NetrateF AS bit  
    DECLARE @QTY AS Float  
    DECLARE @FLPct AS Float  
    DECLARE @Ujroh AS Float  
      
    SET @NetrateF = (SELECT   
           CASE WHEN @P_NetRate = 0 THEN   
                          0  
                     ELSE   
                          1  
                     END)  
    SET @QTY = (SELECT   
      CASE WHEN @P_QTY = 0 THEN   
           1  
                ELSE   
                     @P_QTY  
                END)  
      
    SET @FLPct = ( SELECT   
                   CASE WHEN @P_FLPct = 0 THEN   
                     @P_Share / 100 *  @P_RShare / 100  
         ELSE   
          1  
                   END )  
      
    SET @Ujroh = ( SELECT   
         CASE WHEN @P_Ujroh = 0 THEN  
          1  
         ELSE  
          (100.0 - @P_Ujroh)/100.0  
         END )  
       
    IF @NetRateF = 0 --FOR NETRATEF = 0  
    BEGIN  
        IF @P_FullCoverF = 1   
        BEGIN  
            SELECT @FacPremium = SUM((Case   
                    When P.Description<>'' and P.Description<>'Minimum Premium' THEN   
                     I.GROSS*P.GROSS/P.OGROSS   
                    else   
                     I.GROSS*RC.GROSS/RC.OGROSS   
                    end) /I.prorata  
                    )  
                    *Max(isnull(I2.Share/100,1))  
            FROM   ICalc I  
                INNER JOIN Acceptance A1 ON (A1.Ano = I.ANO)  
                   INNER JOIN Acceptance A2 ON (A2.Ano = I.SANO)  
                   LEFT JOIN ISource I2 ON (A2.CNO = I2.CNO),   
                   RARRDET R,  
                   PCalc AS P,  
                   RCalc AS RC,  
                   Cover  
                     
            WHERE  I.ANO = @P_ANO  
              AND  COVER.CNO = A1.CNO  
              AND  I.CURRENCY = @P_CCY  
              AND  I.SDATE = @P_SDate  
              AND  I.EDATE = @P_EDate  
              AND  I.Code = @P_Code  
              AND  I.INO = @P_INO  
              AND  I.TOR = @P_TOR  
              AND  R.ANO = I.ANO  
              AND  R.FID = @P_FID  
              AND  I.ANO = P.ANO  
              AND  I.Currency = P.CURRENCY  
              AND  I.ANO = RC.ANO  
              AND  I.Currency = RC.Currency  
              AND  I.Code = RC.Code  
              AND  I.TOR = RC.TOR  
              AND  I.SDATE=RC.SDATE   
              AND  I.EDATE=RC.EDATE   
              AND  I.SANO=RC.SANO              
        END  
        ELSE   
        BEGIN  
            SELECT @FacPremium = sum((Case   
                     When P.Description<>'' and P.Description<>'Minimum Premium' then   
                       I.GROSS*P.GROSS/P.OGROSS   
                     else   
                       I.GROSS*RC.GROSS/RC.OGROSS   
                     end) / I.Prorata  
                     )  
                                      * max(Isnull(I2.Share/100,1))  
            FROM   Icalc I  
                INNER JOIN Acceptance A1 ON (A1.Ano = I.ANO)  
                   INNER JOIN Acceptance A2 ON (A2.Ano = I.SANO)  
                   LEFT JOIN ISource I2 ON (A2.CNO = I2.CNO),  
                   RARRDET R,  
                   FPartDet FD,  
                   PCALC P,  
                   RCALC RC,  
                   COVER  
            WHERE  I.ANO = @P_ANO  
              AND  COVER.CNO = A1.CNO  
              AND  I.CURRENCY = @P_CCY  
              AND  I.SDATE = @P_SDate  
              AND  I.EDATE = @P_EDate  
              AND  I.Code = @P_Code  
              AND  I.INO = @P_INO  
              AND  I.TOR = @P_TOR  
              AND  I.ANO = R.ANO  
              AND  R.FID = @P_FID  
              AND  R.ANO = FD.ANO  
              AND  R.FID = fd.FID  
              AND  I.Code = FD.Code  
              AND  I.ANO = p.ANO  
              AND  I.CURRENCY = P.Currency  
              AND  I.ANO = RC.ANO  
              AND  I.Currency = RC.Currency  
              AND  I.Code = RC.Code  
              AND  I.TOR = RC.TOR  
              AND  I.SDATE = RC.SDATE  
              AND  I.EDATE = RC.EDATE  
              AND  I.SANO = RC.SANO  
        END  
    END  
    ELSE --FOR NETRATEF = 1  
    BEGIN  
        IF @P_FullCoverF = 1  
        BEGIN  
            SELECT @FacPremium = sum(CASE   
                    WHEN FPart.NetRate <> 0 THEN  
                  FPart.NetRate/100/PCALC.RiskNum          
                                          *(CASE   
                                            WHEN RArrDet.PCalc='P' OR datediff(month,RArrDet.SDate,RArrDet.EDate)=0 OR Cover.Voyage=1 THEN   
                                                 1  
                                            ELSE   
                                                 12/cast(datediff(month,RArrDet.SDate,RArrDet.EDate)AS float)  
                                            END)              
                                           *ICALC.GROSS/PCALC.GROSS*ICALC.TSI  
                                           *ICALC.PCTADJ/100  
                                     ELSE  
                                           (ICALC.GROSS/PCALC.POGROSS*PCALC.PGROSS)/ICALC.PRORATA  
                                     END)   
                                     *max(Isnull(I2.Share/100,1))  
            FROM   ICALC  
                INNER JOIN Acceptance A1 ON (A1.Ano = ICalc.ANO)  
                   INNER JOIN Acceptance A2 ON (A2.Ano = ICalc.SANO)  
                   LEFT JOIN ISource I2 ON (A2.CNO = I2.CNO),  
                   ICOVER,  
                   PCALC_ANNUM(@P_ANO) PCALC,  
                   FPART,  
                   RARRDET,  
                   COVER                     
         
            WHERE  FPART.ANO = RARRDET.ANO  
              AND  FPART.FID = RARRDET.FID  
              AND  FPART.FID = @P_FID  
              AND  RARRDET.ANO = @P_SANO  
              AND  ICOVER.INO = ICALC.INO  
              AND  (  
                       ICOVER.ADJUSTABLE = @P_ADJUSTABLEF  
                   OR  A1.ATYPE = 'A'  
                   )  
              AND  ICALC.ANO = @P_ANO  
              AND  ICALC.CURRENCY = @P_CCY  
              AND  PCALC.ANO = ICALC.ANO  
              AND  PCALC.CODE = ICALC.CODE  
              AND  PCALC.SDATE = ICALC.SDATE  
              AND  PCALC.EDATE = ICALC.EDATE  
              AND  PCALC.INO = ICALC.INO  
              AND  PCALC.CURRENCY = ICALC.CURRENCY  
              AND  ICALC.SDATE = @P_SDATE  
              AND  ICALC.EDATE = @P_EDATE  
              AND  ICALC.CODE = @P_CODE  
              AND  ICALC.INO = @P_INO  
              AND  ICALC.TOR = @P_TOR  
              AND  COVER.CNO = A1.CNO  
              AND  PCALC.GROSS<>0  
              AND  RARRDET.STATUS<>'O'  
              AND  RARRDET.FULLCOVERF = 1  
        END  
        ELSE   
        BEGIN                     
            SELECT @FacPremium = sum(CASE   
                    WHEN FPart.NetRate <> 0 THEN  
                  FPart.NetRate/100
                                          *(CASE   
                                            WHEN RArrDet.PCalc='P' OR datediff(month,RArrDet.SDate,RArrDet.EDate)=0 OR Cover.Voyage=1 THEN   
                                                 1  
                                            ELSE   
                                                 12/cast(datediff(month,RArrDet.SDate,RArrDet.EDate)AS float)  
                                            END)              
                                           *ICALC.GROSS/PCALC.GROSS*ICALC.TSI  
                                           *ICALC.PCTADJ/100  
                                     ELSE  
                                           (ICALC.GROSS/PCALC.POGROSS*PCALC.PGROSS)/ICALC.PRORATA  
                                     END)   
                                     *max(Isnull(I2.Share/100,1))  
            FROM   ICALC  
                INNER JOIN Acceptance A1 ON (A1.Ano = ICalc.ANO)  
                   INNER JOIN Acceptance A2 ON (A2.Ano = ICalc.SANO)  
                   LEFT JOIN ISource I2 ON (A2.CNO = I2.CNO),  
                   ICOVER,  
                   PCALC_ANNUM(@P_ANO) PCALC,  
                   FPARTDET FPART,  
                   RARRDET,  
                   COVER  
            WHERE  FPART.ANO = RARRDET.ANO  
              AND  FPART.FID = RARRDET.FID  
              AND  FPART.FID = @P_FID  
              AND  FPART.CODE = @P_CODE  
              AND  RARRDET.ANO = @P_SANO  
              AND  ICOVER.INO = ICALC.INO  
              AND  (  
                       ICOVER.ADJUSTABLE = @P_ADJUSTABLEF  
                   OR  A1.ATYPE = 'A'  
                   )  
              AND  ICALC.ANO = @P_ANO  
              AND  ICALC.CURRENCY = @P_CCY  
              AND  PCALC.ANO = ICALC.ANO  
              AND  PCALC.CODE = ICALC.CODE  
              AND  PCALC.SDATE = ICALC.SDATE  
              AND  PCALC.EDATE = ICALC.EDATE  
              AND  PCALC.INO = ICALC.INO  
              AND  PCALC.CURRENCY = ICALC.CURRENCY  
              AND  ICALC.SDATE = @P_SDATE  
              AND  ICALC.EDATE = @P_EDATE  
              AND  ICALC.CODE = @P_CODE  
              AND  ICALC.INO = @P_INO  
              AND  ICALC.TOR = @P_TOR  
              AND  COVER.CNO = A1.CNO  
              AND  PCALC.GROSS<>0  
              AND  RARRDET.STATUS<>'O'  
              AND  RARRDET.FULLCOVERF = 0  
        END  
    END  
      
    SET @Premium = @FacPremium * @Qty * @FLPct * @Ujroh  
    RETURN(@Premium)  
END


GO
/****** Object:  UserDefinedFunction [dbo].[FacProrata]    Script Date: 3/2/2016 9:49:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create Function [dbo].[FacProrata](@P_ANO as int,@FID as varchar(255),@FullCoverF as bit,@SDate as SmallDatetime, @EDate as SmallDatetime, @RSDate as SmallDatetime, @REDate as SmallDateTime, @NetRate as float,@Code as varchar(10) )      
Returns Float              
As      
BEGIN      
 Declare @FacProrata as Float      
 declare @FSDATE smalldatetime, @FEDATE smalldatetime,@NetRateF Bit    
     
 set @NetrateF = (select (case when @NetRate = 0 then 0 else 1 end))    
 set @FSDate = (select case when DateDiff(day,@SDate,@RSDate) >= 0 then @RSDate else @SDate end)    
 set @FEDate = (select case when DateDiff(day,@REDate,@EDate) >= 0 then @REDate else @EDate end)    
    
 Select     
 @FacProrata =     
 case     
 when datediff(day,@FSDate,@FEDate) > 0 then --in periode    
      case     
      when Cover.Voyage = 1 Then    
    	   Icalc.Prorata  
      when Acceptance.Atype = 'A' then  
	   --Check Day Basis  
	   (  
	   case   
	   --Day Basis  
	   when day(@FSDate) <> day(@FEDATE) or Cover.PPeriod = 1 then  
	      CONVERT(float,Datediff(day,@FSDATE,@FEDATE)) / CONVERT(float,Datediff(day,Acceptance.Sdate,DateAdd(Month, 12, Acceptance.Sdate)))  
	   else  
	   --Monthly Basis  
	      CONVERT(float,Datediff(month,@FSDATE,@FEDATE)) / 12.0  
	   end  
	   )                
      when RarrDet.PCalc = 'F' and Not (@NetRateF=1) then    
     	   ICalc.Prorata    
      when RarrDet.PCalc = 'P' and RarrDet.CPCT <> 0 then    
     	   Convert(float,RarrDet.CPCT) / 100    
      ELSE    
    	   case    
           when datediff(Month,@SDate,@EDate) <> 0 then    
     	 	case    
                when RarrDet.Pcalc = 'F' then    
       		     CONVERT(float,DateDiff(Month, @FSDate, @FEDate)) / 12.0   
  		else    
          	     case    
       		     when not(@NetRateF = 1) THEN   
     		          case     
     			  when RarrDet.PCalc = 'P' then    
          		       case    
          		       when Day(@FSDate) = day(@FEDate) And day(@SDate) = day(@EDate) and Cover.PPeriod <> 1 then    
             			    convert(float,datediff(Month,@FSDate,@FEDate))/12.0    
          		       else    
             			    convert(float,datediff(day,@FSDate,@FEDate))/convert(Float,DateDiff(day,@Sdate,DateAdd(Month,12,@Sdate)))    
          		       end    
     			  Else    
          		       case    
          		       when Day(@FSDate) = day(@FEDate) And day(@SDate) = day(@EDate) and Cover.PPeriod <> 1 then    
             			    convert(float,datediff(Month,@FSDate,@FEDate))/convert(float,datediff(Month,@SDate,@EDate))    
          		       else
        			    convert(float,datediff(day,@FSDate,@FEDate))/convert(float,DateDiff(day,@Sdate,@Edate))    
          		       end
     		          end   
       		     Else 
     			  Case    
     			  when Day(@FSDate) = day(@FEDate) And day(@SDate) = day(@EDate) and Cover.PPeriod <> 1 then    
          		       convert(float,Datediff(Month,@FSDate,@FEDate))/12.0    
     			  else    
          		       convert(float,dateDiff(Day,@FSDate,@FEDate))/convert(float,datediff(day,@SDate,dateadd(Month,12,@SDate)))    
     			  end
       		     end    
  		end    
           else    
 	        case     
  		when RarrDet.PCalc = 'P' then    
       		     convert(float,datediff(day,@FSDate,@FEDate))/convert(float,datediff(day,@SDate,dateadd(Month,12,@SDate)))    
  		else    
       		     ICalc.Prorata    
  		end    
    	   end    
      end    
 else  
      0
 end   
 FROM
  Acceptance
  inner join Cover on (Cover.CNO = Acceptance.CNO)
  inner join RArrDet on (RarrDet.ANO = Acceptance.Ano)
  inner join ICalc on (Acceptance.ANO = ICalc.ANO)
 WHERE
  Acceptance.ANO=@P_ANO and ICalc.Gross <> 0
  and RarrDet.FID = @FID
  and ICalc.Sdate = @SDate and ICalc.EDate = @EDate and ICalc.Code = @Code
  Return(@FacProrata)    
END    
  

GO

/****** Object:  UserDefinedFunction [dbo].[Facultative_Calculation]    Script Date: 3/2/2016 9:49:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[Facultative_Calculation](@P_ANO BIGINT)
RETURNS TABLE
AS
RETURN 
(
	
SELECT T.*
,(T.FacPremium * ISNULL(T.UJROHCEDANT,0)/100) AS UjrohPremium
,(T.FacPremium * (100.0 - ISNULL(T.UJROHCEDANT,0))/100.0) as NetPremium
,(T.FacPremium * isnull(T.COMM,0)/100) as Commission
,(T.FacPremium * (100.0 - ISNULL(T.UJROHCEDANT,0))/100.0 * isnull(T.UJROHREINS,0)/100.0) as UjrohFee
from 
(
/*
For Current Acceptance 
Untuk Facultative with Detail FPartDet
*/
SELECT 
	RArrDet.ANO,
	RArrDet.FID,
	RArrDet.FLPct,
	RArrDet.Status,
	RArrDet.AType,
	RArrDet.RType,
	RArrDet.SDate,
	RArrDet.EDate,
	case when DateDiff(Day, ICalc.SDate,RArrDet.SDate) >= 0 then RArrdet.Sdate else ICalc.Sdate end as FSDate,
	case when DateDiff(Day, RArrDet.EDate,ICalc.EDate) >= 0 then RArrdet.Edate else ICalc.Edate end as FEDate,
	RArrDet.Share,
	RArrDet.Amount,
	RArrDet.Prorata,
	Profile.Name,
	FPart.SlipNo,
	FPart.ID,
	FPart.Share AS RShare,
	FPartDet.Comm,
	FPart.WPC,
	FPartDet.NetRate
	* (Case 
	   When RArrDet.PCalc='P' or datediff(month,RArrDet.SDate, RArrDet.EDate)=0 or Cover.Voyage=1 Then 
		1 
	   else 
		case 
		when datediff(month,RarrDet.SDate,RarrDet.EDate) <= 12 or (Acceptance.SDate = ICalc.SDate and Acceptance.EDate = ICalc.Edate)then
		     1
		else
		     12/cast(datediff(month,RArrDet.SDate, RArrDet.EDate) as float)
		end 
	   end) as NetRate,
	RArrdet.PCalc,
	RArrDet.CPCT,
	RArrDet.FullCoverF,
	Fpart.remarks,
	ICalc.Currency,
	ICalc.Code,
	ICalc.Sdate as [ISdate],
	ICalc.Edate as IEdate,
	ICalc.INO,
	ICalc.TOR,
	(case when PCALC.[Description]<>'' and PCALC.[Description]<>'Minimum Premium' then ICALC.GROSS*PCALC.GROSS/PCALC.OGROSS else ICALC.GROSS*RCALC.GROSS/RCALC.OGROSS end) as Premium,
	ICalc.Rate,
	ICalc.SRate,
	ICalc.Prorata AS PProrata,
	ICalc.SProrata AS SProrata,
	ICalc.PctLoss,
	ICalc.PctAdj,
	ICalc.TSI*(PCALC.OURSHARE/PCALC.TSI) as TSI,
	ICalc.Discount,
 	dbo.FacProrata(RarrDet.Ano,RarrDet.FID,Rarrdet.FullCoverF,ICalc.SDate,ICalc.EDate,RarrDet.SDate,RarrDet.EDate,FPartDet.NetRate,FPartDet.Code) as FacProrata,
	dbo.FacPremium(ICalc.SANO,ICalc.ANO,RArrDet.FID,ICalc.Currency,ICalc.SDate,ICalc.EDate,ICalc.Code,ICalc.INO,ICalc.TOR,ICover.Adjustable,RarrDet.FullCoverF,FPartDet.NetRate,Acceptance.QTY,RarrDet.FLPct,RarrDet.Share,Fpart.Share,0)
	*  dbo.FacProrata(RarrDet.Ano,RarrDet.FID,Rarrdet.FullCoverF,ICalc.SDate,ICalc.EDate,RarrDet.SDate,RarrDet.EDate,FPartDet.NetRate,FPartDet.Code) as FACPremium,
	dbo.sFacProrata(RarrDet.Ano,RarrDet.FID,Rarrdet.FullCoverF,ICalc.SDate,ICalc.EDate,RarrDet.SDate,RarrDet.EDate,FPartDet.NetRate,FPartDet.Code) as sFacProrata,
	Case when Acceptance.Qty = 0 then 1 else Acceptance.Qty end as Qty,
	RarrDet.MEMO,
	Acceptance.ANO AS OANO,
	RarrDet.UJROHREINS,
	RarrDet.UJROHCEDANT
FROM 
Acceptance
inner join Cover on (Cover.CNO = Acceptance.CNO)
inner join RArrDet on (RarrDet.ANO = Acceptance.Ano)
inner join FPart on (Acceptance.Ano = FPart.Ano and RarrDet.FID = Fpart.FID)
inner join Profile on (FPart.ID = Profile.ID)
inner join ICalc on (Acceptance.ANO = ICalc.ANO)
inner join ICover on (ICalc.INO = ICover.INO)
inner join FpartDet on (Acceptance.ANO = FPartDet.Ano and RarrDet.FID = FPartDet.FID and ICalc.Code = FPartDet.Code)
inner join PCalc on (ICalc.Ano = PCalc.Ano and ICalc.Currency = PCalc.Currency)
inner join RCALC on (ICALC.ANO=RCALC.ANO AND ICALC.CURRENCY=RCALC.CURRENCY AND ICALC.CODE=RCALC.CODE AND ICALC.TOR=RCALC.TOR AND ICALC.SDATE=RCALC.SDATE AND ICALC.EDATE=RCALC.EDATE)
left join RCover on (Acceptance.ANO = RCover.ANO and RCover.Code = ICalc.Code and RCover.SDate = ICalc.SDate and RCover.EDate = ICalc.EDate)
WHERE 
Acceptance.ANO = @P_ANO and RArrDet.FullCoverF<>1 and PCalc.Gross <> 0 and ICalc.Gross <> 0 
and (RarrDet.Atype = 'N' or (Acceptance.NoRefundF = 0 and (Case when RCover.ANO is Null then 0 else RCover.NoRefundF end) = 0))
and Acceptance.AType not in ('C')

UNION ALL  
/*
Untuk Facultative yang Netrate <> 0
*/
SELECT 
	RArrDet.ANO,
	RArrDet.FID,
	RArrDet.FLPct,
	RArrDet.Status,
	RArrDet.AType,
	RArrDet.RType,
	RArrDet.SDate,
	RArrDet.EDate,
	case when DateDiff(Day, ICalc.SDate,RArrDet.SDate) >= 0 then RArrdet.Sdate else ICalc.Sdate end as FSDate,
	case when DateDiff(Day, RArrDet.EDate,ICalc.EDate) >= 0 then RArrdet.Edate else ICalc.Edate end as FEDate,
	RArrDet.Share,
	RArrDet.Amount,
	RArrDet.Prorata,
	Profile.Name,
	FPart.SlipNo,
	FPart.ID,
	FPart.Share AS RShare,
	FPart.Comm,
	FPart.WPC,
	FPart.NetRate
	* (Case 
	   When RArrDet.PCalc='P' or datediff(month,RArrDet.SDate, RArrDet.EDate)=0 or Cover.Voyage=1 Then 
		1 
	   else 
		case 
		when datediff(month,RarrDet.SDate,RarrDet.EDate) <= 12 or (Acceptance.SDate = ICalc.SDate and Acceptance.EDate = ICalc.Edate) then
		     1
		else
		     12/cast(datediff(month,RArrDet.SDate, RArrDet.EDate) as float)
		end 
	   end) as NetRate,
	RArrdet.PCalc,
	RArrDet.CPCT,
	RArrDet.FullCoverF,
	Fpart.remarks,
	ICalc.Currency,
	ICalc.Code,
	ICalc.Sdate as [ISdate],
	ICalc.Edate as IEdate,
	ICalc.INO,
	ICalc.TOR,
	(case when PCALC.[Description]<>'' and PCALC.[Description]<>'Minimum Premium' then ICALC.GROSS*PCALC.GROSS/PCALC.OGROSS else ICALC.GROSS*RCALC.GROSS/RCALC.OGROSS end) as Premium,
	ICalc.Rate,
	ICalc.SRate,
	ICalc.Prorata AS PProrata,
	ICalc.SProrata AS SProrata,
	ICalc.PctLoss,
	ICalc.PctAdj,
	ICalc.TSI*(PCALC.OURSHARE/PCALC.TSI) as TSI,
	ICalc.Discount,
	dbo.FacProrata(RarrDet.Ano,RarrDet.FID,Rarrdet.FullCoverF,ICalc.SDate,ICalc.EDate,RarrDet.SDate,RarrDet.EDate,FPart.NetRate,ICalc.Code) as FacProrata,
	dbo.FacPremium(ICalc.SANO,ICalc.ANO,RArrDet.FID,ICalc.Currency,ICalc.SDate,ICalc.EDate,ICalc.Code,ICalc.INO,ICalc.TOR,ICover.Adjustable,RarrDet.FullCoverF,FPart.NetRate,Acceptance.QTY,RarrDet.FLPct,RarrDet.Share,Fpart.Share,0)
 	*  dbo.FacProrata(RarrDet.Ano,RarrDet.FID,Rarrdet.FullCoverF,ICalc.SDate,ICalc.EDate,RarrDet.SDate,RarrDet.EDate,FPart.NetRate,ICalc.Code) as FACPremium,
	dbo.sFacProrata(RarrDet.Ano,RarrDet.FID,Rarrdet.FullCoverF,ICalc.SDate,ICalc.EDate,RarrDet.SDate,RarrDet.EDate,FPart.NetRate,ICalc.Code) as sFacProrata,
	Case when Acceptance.Qty = 0 then 1 else Acceptance.Qty end as Qty,
	RarrDet.MEMO,
	ACCEPTANCE.ANO AS OANO,
	RarrDet.UJROHREINS,
	RarrDet.UJROHCEDANT
FROM
Acceptance
inner join Cover on (Cover.CNO = Acceptance.CNO)
inner join RArrDet on (RarrDet.ANO = Acceptance.Ano)
inner join FPart on (Acceptance.Ano = FPart.Ano and RarrDet.FID = Fpart.FID)
inner join Profile on (FPart.ID = Profile.ID)
inner join ICalc on (Acceptance.ANO = ICalc.ANO)
inner join ICover on (ICalc.INO = ICover.INO)
inner join PCalc on (ICalc.Ano = PCalc.Ano and ICalc.Currency = PCalc.Currency)
inner join RCALC on (ICALC.ANO=RCALC.ANO AND ICALC.CURRENCY=RCALC.CURRENCY AND ICALC.CODE=RCALC.CODE AND ICALC.TOR=RCALC.TOR AND ICALC.SDATE=RCALC.SDATE AND ICALC.EDATE=RCALC.EDATE)
left join RCover on (Acceptance.ANO = RCover.ANO and RCover.Code = ICalc.Code and RCover.SDate = ICalc.SDate and RCover.EDate = ICalc.EDate)
WHERE
Acceptance.ANO=@P_ANO AND RArrDet.FullCoverF=1 and Fpart.Netrate <> 0 and PCalc.Gross <> 0 and ICalc.Gross <> 0
and (RarrDet.Atype = 'N' or (Acceptance.NoRefundF = 0 and (Case when RCover.ANO is Null then 0 else RCover.NoRefundF end) = 0))
and Acceptance.AType not in ('C')


UNION ALL
/*
Untuk Facultative yang net rate = 0 dan FullcoverF = 1
*/
SELECT 
	RArrDet.ANO,
	RArrDet.FID,
	RArrDet.FLPct,
	RArrDet.Status,
	RArrDet.AType,
	RArrDet.RType,
	RArrDet.SDate,
	RArrDet.EDate,
	case when DateDiff(Day, ICalc.SDate,RArrDet.SDate) >= 0 then RArrdet.Sdate else ICalc.Sdate end as FSDate,
	case when DateDiff(Day, RArrDet.EDate,ICalc.EDate) >= 0 then RArrdet.Edate else ICalc.Edate end as FEDate,
	RArrDet.Share,
	RArrDet.Amount,
	RArrDet.Prorata,
	Profile.Name,
	FPart.SlipNo,
	FPart.ID,
	FPart.Share AS RShare,
	FPart.Comm,
	FPart.WPC,
	FPart.NetRate
	* (Case 
	   When RArrDet.PCalc='P' or datediff(month,RArrDet.SDate, RArrDet.EDate)=0 or Cover.Voyage=1 Then 
		1 
	   else 
		case 
		when datediff(month,RarrDet.SDate,RarrDet.EDate) <= 12 or (Acceptance.SDate = ICalc.SDate and Acceptance.EDate = ICalc.Edate) then
		     1
		else
		     12/cast(datediff(month,RArrDet.SDate, RArrDet.EDate) as float)
		end 
	   end) as NetRate,
	RArrdet.PCalc,
	RArrDet.CPCT,
	RArrDet.FullCoverF,
	Fpart.remarks,
	ICalc.Currency,
	ICalc.Code,
	ICalc.Sdate as [ISdate],
	ICalc.Edate as IEdate,
	ICalc.INO,
	ICalc.TOR,
	(case when PCALC.[Description]<>'' and PCALC.[Description]<>'Minimum Premium' then ICALC.GROSS*PCALC.GROSS/PCALC.OGROSS else ICALC.GROSS*RCALC.GROSS/RCALC.OGROSS end) as Premium,
	ICalc.Rate,
	ICalc.SRate,
	ICalc.Prorata AS PProrata,
	ICalc.SProrata AS SProrata,
	ICalc.PctLoss,
	ICalc.PctAdj,
	ICalc.TSI*(PCALC.OURSHARE/PCALC.TSI) as TSI,
	ICalc.Discount,
 	dbo.FacProrata(RarrDet.Ano,RarrDet.FID,Rarrdet.FullCoverF,ICalc.SDate,ICalc.EDate,RarrDet.SDate,RarrDet.EDate,FPart.NetRate,ICalc.Code) as FacProrata,
	dbo.FacPremium(ICalc.SANO,ICalc.ANO,RArrDet.FID,ICalc.Currency,ICalc.SDate,ICalc.EDate,ICalc.Code,ICalc.INO,ICalc.TOR,ICover.Adjustable,RarrDet.FullCoverF,FPart.NetRate,Acceptance.QTY,RarrDet.FLPct,RarrDet.Share,Fpart.Share,0) 
	*  dbo.FacProrata(RarrDet.Ano,RarrDet.FID,Rarrdet.FullCoverF,ICalc.SDate,ICalc.EDate,RarrDet.SDate,RarrDet.EDate,FPart.NetRate,ICalc.Code) 
	as FACPremium,
 	dbo.sFacProrata(RarrDet.Ano,RarrDet.FID,Rarrdet.FullCoverF,ICalc.SDate,ICalc.EDate,RarrDet.SDate,RarrDet.EDate,FPart.NetRate,ICalc.Code) as sFacProrata,
	Case when Acceptance.Qty = 0 then 1 else Acceptance.Qty end as Qty,
	RarrDet.MEMO,
	ACCEPTANCE.ANO AS OANO,
	RarrDet.UJROHREINS,
	RarrDet.UJROHCEDANT
FROM
Acceptance
inner join Cover on (Cover.CNO = Acceptance.CNO)
inner join RArrDet on (RarrDet.ANO = Acceptance.Ano)
inner join FPart on (Acceptance.Ano = FPart.Ano and RarrDet.FID = Fpart.FID)
inner join Profile on (FPart.ID = Profile.ID)
inner join ICalc on (Acceptance.ANO = ICalc.ANO)
inner join ICover on (ICalc.INO = ICover.INO)
inner join PCalc on (ICalc.Ano = PCalc.Ano and ICalc.Currency = PCalc.Currency)
inner join RCALC on (ICALC.ANO=RCALC.ANO AND ICALC.CURRENCY=RCALC.CURRENCY AND ICALC.CODE=RCALC.CODE AND ICALC.TOR=RCALC.TOR AND ICALC.SDATE=RCALC.SDATE AND ICALC.EDATE=RCALC.EDATE)
left join RCover on (Acceptance.ANO = RCover.ANO and RCover.Code = ICalc.Code and RCover.SDate = ICalc.SDate and RCover.EDate = ICalc.EDate)
WHERE 
Acceptance.ANO=@P_ANO and RArrDet.FullCoverF=1 and Fpart.Netrate = 0 and PCalc.Gross <> 0 and ICalc.Gross <> 0 
and (Acceptance.NoRefundF = 0 or RCover.NoRefundF = 0)
and (RarrDet.Atype = 'N' or (Acceptance.NoRefundF = 0 and (Case when RCover.ANO is Null then 0 else RCover.NoRefundF end) = 0))
and Acceptance.AType not in ('C')


