	* dbo.FacProrata(RarrDet.Ano,RarrDet.FID,Rarrdet.FullCoverF,ICalc.SDate,ICalc.EDate,RarrDet.SDate,RarrDet.EDate,FPartDet.NetRate,FPartDet.Code) as FACPremium,
 	dbo.sFacProrata(RarrDet.Ano,RarrDet.FID,Rarrdet.FullCoverF,ICalc.SDate,ICalc.EDate,RarrDet.SDate,RarrDet.EDate,FPartDet.NetRate,FPartDet.Code) as sFacProrata,
	Case when Acceptance.Qty = 0 then 1 else Acceptance.Qty end as Qty,
