/****** Object:  UserDefinedFunction [dbo].[FACULTATIVE_PREMIUM_CALCULATION_CONSTANT_ADJUSTMENT]    Script Date: 3/2/2016 9:49:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[FACULTATIVE_PREMIUM_CALCULATION_CONSTANT_ADJUSTMENT](@P_ANO int, @P_FID as varchar(20)) 
RETURNS TABLE  AS 
RETURN ( 
	select A1.ANO, AccAss.Currency_OC as Currency, 
	sum(Case When AccAss.Code='P' then (Case When A1.AType='A' and AccAss.AdjMethod='OVERLIMIT' then -AccAss.CAmount*(Case When A1.CPCT<>0 Then A1.CPCT/100 else 1 end)/(Case When AccAss.PProrata<>0 Then AccAss.PProrata else 1 end) else -AccAss.Amount_OC end) else 0 end) as Premium 
	From Acceptance A1 
	inner join Acceptance A2 on (A2.OANO=A1.OANO) 
	Left join Acceptance pA1  on (pA1.ANO=A2.pANO) 
	inner Join RArrDet on (RArrDet.ANO=A2.ANO and RArrDet.FID=@P_FID) 
	Inner Join FPart on (FPart.ANO=RArrDet.ANO and FPart.FID=RArrDet.FID) 
	inner join AccAss on (AccAss.ANO=A2.ANO and AccAss.RefNo=FPart.SlipNo and AccAss.ID=FPart.ID) 
	Where A1.ANO=@P_ANO and A2.ANO<A1.ANO 
	and ( 
	(A2.ANO<=A1.PANO and A1.PDate<=A2.PDate and A1.PPDate>=A2.PPDate and A1.AType='A' and (A2.AType<>'A' and coalesce(pA1.AType,'')<>'A') and AccAss.AdjustableF=1 and (AccAss.AdjMethod<>'OVERLIMIT' or AccAss.CAmount<>0) and NOT EXISTS (Select PANO from Acceptance A3 Where A3.PANO=A2.ANO and A3.Astatus<>'C' and A3.AType='A' and A3.ANO<>@P_ANO)) 
	or (A1.AType='C' and A1.EMethod='A' and A2.PDate>=A1.PDate and (coalesce(pA1.pDate,A2.PDate)>=A1.PDate or A2.ATYPE='A' or (coalesce(pA1.pDate,A2.PDate)<A1.PDate and AccAss.CAmount<>0))) 
	) 
	and AccAss.Code='P' 
	Group By A1.ANO, AccAss.Currency_OC 
) 
 
GO 
 

CREATE Function [dbo].[GetPrivileges](@UserID varchar(50), @FName varchar(50)) 
RETURNS BIT AS 
BEGIN 
   Declare @UserRights as int 
   Declare @WriteRights as int 
   Declare @Privilege as Bit 
   Select @writeRights =2 
   Select @UserRights=dbo.GetUserRights(@UserID, @FName) 

if (@UserRights & @writeRights)=@WriteRights 
       Select @Privilege=1 
   else 
       Select @Privilege=0 
   return @Privilege 
END 
 
GO


/****** Object:  UserDefinedFunction [dbo].[GetUserRights]    Script Date: 3/4/2016 1:14:19 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Function [dbo].[GetUserRights](@UserID varchar(50), @FName varchar(50)) 
RETURNS INT AS 
BEGIN 
 
Declare @ReadF as bit 
Declare @WriteF as bit 
Declare @AddF as bit 
Declare @DeleteF as bit 
Declare @CheckF as bit 
 
Declare @UserRights as int 
Select @UserRights=0 
 
Select @FName=FName from SysForm Where FName=@FName 
 
if @FName is null 
	return 0 
else 
Begin 
	Select @ReadF=S1.ReadF, @WriteF=S1.WriteF, @AddF=S1.AddF, @DeleteF=S1.DeleteF, @CheckF=S1.CheckF from SysUserForm S1, SysUser S2 where S1.Type=S2.Type and S2.ID=@UserID and S1.FName=@FName 
	if coalesce(@ReadF,0)=1 
		Select @UserRights = @UserRights | power(2,0) 
	if coalesce(@WriteF,0)=1 
		Select @UserRights = @UserRights | power(2,1) 
	if coalesce(@AddF,0)=1 
		Select @UserRights = @UserRights | power(2,2) 
	if coalesce(@DeleteF,0)=1 
		Select @UserRights = @UserRights | power(2,3) 
	if coalesce(@CheckF,0)=1 
		Select @UserRights = @UserRights | power(2,4) 
 
	Select @ReadF=S1.ReadF, @WriteF=S1.WriteF, @AddF=S1.AddF, @DeleteF=S1.DeleteF, @CheckF=S1.CheckF from sysusergrants S1 Where S1.ID=@UserID and S1.FName=@FName 
	if coalesce(@ReadF,0)=1 
		Select @UserRights = @UserRights | power(2,0) 
	if coalesce(@WriteF,0)=1 
		Select @UserRights = @UserRights | power(2,1) 
	if coalesce(@AddF,0)=1 
		Select @UserRights = @UserRights | power(2,2) 
	if coalesce(@DeleteF,0)=1 
		Select @UserRights = @UserRights | power(2,3) 
	if coalesce(@CheckF,0)=1 
		Select @UserRights = @UserRights | power(2,4)			 
end 
	 
return @UserRights 
END 

GO 


